export const GAME_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n  <title>Super Mario 3D Edge \u2022 Official Style</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link href=\"https://fonts.googleapis.com/css2?family=Press+Start+2P&family=Fredoka:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js\"></script>\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; user-select: none; }\n    body {\n      background: #0b1329;\n      color: #fff;\n      font-family: 'Press Start 2P', cursive;\n      overflow: hidden;\n      height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n    }\n    #gameWrapper {\n      position: relative;\n      width: 100vw;\n      height: 100vh;\n      background: #000;\n      overflow: hidden;\n    }\n    #c {\n      width: 100%;\n      height: 100%;\n      display: block;\n    }\n    /* Modern Glossy Nintendo HUD */\n    .hud {\n      position: absolute;\n      top: 18px;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 92%;\n      max-width: 900px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      background: rgba(15, 23, 42, 0.72);\n      border: 2px solid rgba(255, 255, 255, 0.2);\n      backdrop-filter: blur(12px);\n      border-radius: 20px;\n      padding: 12px 28px;\n      font-size: 11px;\n      letter-spacing: 1.5px;\n      text-shadow: 2px 2px 4px rgba(0,0,0,0.8);\n      pointer-events: none;\n      z-index: 20;\n      box-shadow: 0 12px 35px rgba(0,0,0,0.6);\n    }\n    .hud-col { display: flex; flex-direction: column; align-items: center; gap: 5px; }\n    .hud-title { color: #f87171; font-size: 9px; letter-spacing: 1px; }\n    .hud-val { color: #fff; font-size: 12px; }\n    .coin-icon {\n      display: inline-block;\n      width: 12px;\n      height: 14px;\n      background: #fbbf24;\n      border: 2px solid #b45309;\n      border-radius: 50%;\n      vertical-align: middle;\n      margin-right: 6px;\n      box-shadow: 0 0 10px #f59e0b;\n    }\n    /* Overlays */\n    .overlay {\n      position: absolute;\n      top: 0; left: 0; width: 100%; height: 100%;\n      background: rgba(3, 7, 18, 0.85);\n      backdrop-filter: blur(10px);\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      z-index: 30;\n      text-align: center;\n      padding: 24px;\n    }\n    .overlay.hidden { display: none !important; }\n    .overlay h1 {\n      font-size: 32px;\n      background: linear-gradient(180deg, #f87171 0%, #dc2626 100%);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n      margin-bottom: 20px;\n      text-shadow: 0 6px 25px rgba(225, 29, 72, 0.6);\n      line-height: 1.3;\n    }\n    .overlay p {\n      font-size: 11px;\n      line-height: 2.2;\n      color: #cbd5e1;\n      margin-bottom: 28px;\n    }\n    .btn {\n      font-family: 'Press Start 2P', cursive;\n      font-size: 11px;\n      background: #e11d48;\n      color: #fff;\n      border: 3px solid #fff;\n      border-radius: 10px;\n      padding: 16px 28px;\n      cursor: pointer;\n      box-shadow: 0 6px 20px rgba(225, 29, 72, 0.4);\n      transition: all 0.15s;\n      margin: 8px;\n    }\n    .btn:hover { background: #f43f5e; transform: translateY(-3px); box-shadow: 0 10px 30px rgba(244, 63, 94, 0.6); }\n    .btn:active { transform: translateY(2px); }\n    .name-input {\n      font-family: 'Press Start 2P', cursive;\n      font-size: 12px;\n      padding: 14px;\n      background: #0f172a;\n      border: 2px solid #38bdf8;\n      border-radius: 10px;\n      color: #fff;\n      text-align: center;\n      margin-bottom: 20px;\n      outline: none;\n      width: 280px;\n    }\n    .leaderboard-table {\n      width: 100%;\n      max-width: 500px;\n      font-size: 9px;\n      margin-bottom: 24px;\n      border-collapse: collapse;\n    }\n    .leaderboard-table th, .leaderboard-table td {\n      padding: 12px 10px;\n      border-bottom: 1px solid #334155;\n    }\n    .leaderboard-table th { color: #f59e0b; }\n    #mobileControls {\n      position: absolute;\n      bottom: 20px;\n      left: 0;\n      width: 100%;\n      display: none;\n      justify-content: space-between;\n      align-items: flex-end;\n      padding: 0 24px;\n      z-index: 40;\n      pointer-events: none;\n    }\n    .d-pad, .action-btns {\n      display: flex;\n      gap: 14px;\n      align-items: center;\n      pointer-events: auto;\n    }\n    .m-btn {\n      width: 68px;\n      height: 68px;\n      background: rgba(15, 23, 42, 0.78);\n      border: 2.5px solid rgba(255, 255, 255, 0.35);\n      backdrop-filter: blur(12px);\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 20px;\n      font-weight: bold;\n      color: #fff;\n      touch-action: none;\n      user-select: none;\n      box-shadow: 0 8px 25px rgba(0,0,0,0.6);\n      transition: transform 0.08s;\n    }\n    .m-btn:active, .m-btn.active {\n      transform: scale(0.92);\n      filter: brightness(1.2);\n    }\n    .m-btn-jump {\n      width: 76px;\n      height: 76px;\n      background: linear-gradient(135deg, #22c55e, #16a34a);\n      border-color: #86efac;\n      box-shadow: 0 8px 25px rgba(34, 197, 94, 0.5);\n    }\n    .m-btn-fire {\n      width: 70px;\n      height: 70px;\n      background: linear-gradient(135deg, #f97316, #ea580c);\n      border-color: #fdba74;\n      box-shadow: 0 8px 25px rgba(249, 115, 22, 0.5);\n    }\n    .fullscreen-btn {\n      position: absolute;\n      top: 18px;\n      right: 18px;\n      background: rgba(15, 23, 42, 0.75);\n      border: 1.5px solid rgba(255, 255, 255, 0.3);\n      color: #fff;\n      font-size: 16px;\n      padding: 8px 12px;\n      border-radius: 12px;\n      cursor: pointer;\n      z-index: 50;\n      backdrop-filter: blur(8px);\n    }\n    .star-badge {\n      display: none;\n      background: linear-gradient(135deg, #f59e0b, #ec4899);\n      color: #fff;\n      padding: 3px 8px;\n      border-radius: 8px;\n      font-size: 9px;\n    }\n    .speedrun-badge {\n      font-size: 9px;\n      color: #38bdf8;\n      font-family: 'Press Start 2P', cursive;\n    }\n    @media(max-width: 1024px), (hover: none) and (pointer: coarse) {\n      #mobileControls { display: flex; }\n      .hud { font-size: 8px; width: 96%; padding: 8px 12px; top: 10px; }\n      .overlay h1 { font-size: 22px; }\n    }\n  </style>\n</head>\n<body>\n\n  <div id=\"gameWrapper\">\n    <div class=\"hud\">\n      <div class=\"hud-col\"><span class=\"hud-title\">MARIO</span><span class=\"hud-val\" id=\"hudScore\">000000</span></div>\n      <div class=\"hud-col\"><span class=\"hud-title\">COINS</span><span class=\"hud-val\" id=\"hudCoins\"><span class=\"coin-icon\"></span>x00</span></div>\n      <div class=\"hud-col\"><span class=\"hud-title\">WORLD</span><span class=\"hud-val\">1-1</span></div>\n      <div class=\"hud-col\"><span class=\"hud-title\">TIME</span><span class=\"hud-val\" id=\"hudTime\">400</span></div>\n      <div class=\"hud-col\"><span class=\"hud-title\">LIVES</span><span class=\"hud-val\" id=\"hudLives\">x3</span></div>\n      <div class=\"hud-col\" id=\"starHudCol\"><span class=\"star-badge\" id=\"starBadge\">\u2b50 STAR</span><span class=\"speedrun-badge\" id=\"ghostDiffBadge\">GHOST: --</span></div>\n      <div class=\"hud-col\" style=\"cursor:pointer; pointer-events:auto;\" id=\"hudAudioToggle\"><span class=\"hud-title\">MUSIC</span><span class=\"hud-val\" id=\"audioToggleLabel\">\ud83d\udd0a BGM</span></div>\n    </div>\n    <button class=\"fullscreen-btn\" id=\"btnFullscreen\" title=\"Toggle Fullscreen\">\u26f6</button>\n\n    <canvas id=\"c\"></canvas>\n\n    <div class=\"overlay\" id=\"startOverlay\">\n      <h1>SUPER MARIO 3D</h1>\n      <p>A / D / Arrow Keys = Run<br>Space / W / Z = High Jump (Hold for high jump)<br>Shift / X = Dash</p>\n      <button class=\"btn\" id=\"btnStartGame\">START GAME</button>\n      <button class=\"btn\" style=\"background:#3b82f6;\" id=\"btnShowLeaderboard\">LEADERBOARD</button>\n    </div>\n\n    <div class=\"overlay hidden\" id=\"gameOverOverlay\">\n      <h1>GAME OVER</h1><p id=\"finalScoreMsg\">SCORE: 0</p>\n      <input type=\"text\" class=\"name-input\" id=\"playerNameInput\" placeholder=\"YOUR NAME\" maxlength=\"12\">\n      <div><button class=\"btn\" id=\"btnSubmitScore\">SAVE SCORE</button><button class=\"btn\" style=\"background:#475569;\" id=\"btnRetryGame\">RETRY</button></div>\n    </div>\n\n    <div class=\"overlay hidden\" id=\"victoryOverlay\">\n      <h1 style=\"background: linear-gradient(180deg,#4ade80,#16a34a); -webkit-background-clip:text; -webkit-text-fill-color:transparent;\">STAGE CLEAR!</h1>\n      <p id=\"victoryScoreMsg\">YOU CONQUERED THE 3D EDGE!</p>\n      <input type=\"text\" class=\"name-input\" id=\"victoryNameInput\" placeholder=\"YOUR NAME\" maxlength=\"12\">\n      <div><button class=\"btn\" id=\"btnSubmitVictory\">SUBMIT SCORE</button><button class=\"btn\" style=\"background:#475569;\" id=\"btnPlayAgain\">PLAY AGAIN</button></div>\n    </div>\n\n    <div class=\"overlay hidden\" id=\"leaderboardOverlay\">\n      <h1 style=\"background: linear-gradient(180deg,#fbbf24,#d97706); -webkit-background-clip:text; -webkit-text-fill-color:transparent;\">HALL OF FAME</h1>\n      <table class=\"leaderboard-table\"><thead><tr><th>#</th><th>NAME</th><th>SCORE</th><th>COINS</th><th>REGION</th></tr></thead><tbody id=\"leaderboardBody\"><tr><td colspan=\"5\">Loading scores...</td></tr></tbody></table>\n      <button class=\"btn\" id=\"btnHideLeaderboard\">BACK</button>\n    </div>\n\n    <div id=\"mobileControls\">\n      <div class=\"d-pad\"><div class=\"m-btn\" id=\"mLeft\">\u25c0</div><div class=\"m-btn\" id=\"mRight\">\u25b6</div></div>\n      <div class=\"action-btns\"><div class=\"m-btn\" id=\"mFire\" style=\"background:#f97316;\">B</div><div class=\"m-btn\" id=\"mJump\" style=\"background:#22c55e;\">A</div></div>\n    </div>\n  </div>\n\n  <script>\n    // ==================== MARIO BGM CHIPTUNE SYNTHESIZER ====================\n    // Authentic Note Frequencies\n    const N = {\n      R: 0,\n      G3: 196.00, A3: 220.00, B3: 246.94,\n      C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, FS4: 369.99, G4: 392.00, GS4: 415.30, A4: 440.00, AS4: 466.16, B4: 493.88,\n      C5: 523.25, CS5: 554.37, D5: 587.33, DS5: 622.25, E5: 659.25, F5: 698.46, FS5: 739.99, G5: 783.99, GS5: 830.61, A5: 880.00, AS5: 932.33, B5: 987.77,\n      C6: 1046.50\n    };\n\n    let bgmMasterGain = null;\n    let bgmOscillator1 = null;\n    let bgmOscillator2 = null;\n    let isBgmMuted = false;\n    let isBgmPlaying = false;\n    let bgmTimeoutId = null;\n    let isStarmanPlaying = false;\n    let starmanTimeoutId = null;\n\n    const STARMAN_THEME = [\n      [N.C5, 1], [N.E5, 1], [N.G5, 1], [N.C6, 1],\n      [N.B5, 1], [N.G5, 1], [N.E5, 1], [N.C5, 1],\n      [N.D5, 1], [N.F5, 1], [N.A5, 1], [N.D6, 1],\n      [N.C6, 1], [N.A5, 1], [N.F5, 1], [N.D5, 1],\n    ];\n\n    function startStarmanBGM() {\n      stopMarioBGM();\n      if (starmanTimeoutId) clearTimeout(starmanTimeoutId);\n      isStarmanPlaying = true;\n      scheduleStarmanTheme();\n    }\n\n    function stopStarmanBGM() {\n      isStarmanPlaying = false;\n      if (starmanTimeoutId) {\n        clearTimeout(starmanTimeoutId);\n        starmanTimeoutId = null;\n      }\n    }\n\n    function scheduleStarmanTheme() {\n      if (!isStarmanPlaying || gameState !== 'PLAYING') {\n        isStarmanPlaying = false;\n        return;\n      }\n      const ctx = getAudio();\n      let t = ctx.currentTime + 0.04;\n      const unit = 0.085;\n\n      for (let rep = 0; rep < 4; rep++) {\n        for (let i = 0; i < STARMAN_THEME.length; i++) {\n          const [freq, u] = STARMAN_THEME[i];\n          const dur = u * unit;\n          if (!isBgmMuted && freq > 0) {\n            const osc = ctx.createOscillator();\n            const gain = ctx.createGain();\n            osc.type = 'square';\n            osc.frequency.setValueAtTime(freq, t);\n            gain.gain.setValueAtTime(0.09, t);\n            gain.gain.exponentialRampToValueAtTime(0.001, t + dur * 0.9);\n            osc.connect(gain);\n            gain.connect(ctx.destination);\n            osc.start(t);\n            osc.stop(t + dur * 0.95);\n          }\n          t += dur;\n        }\n      }\n\n      const loopMs = (t - ctx.currentTime) * 1000;\n      starmanTimeoutId = setTimeout(() => {\n        if (isStarmanPlaying && gameState === 'PLAYING') scheduleStarmanTheme();\n      }, Math.max(100, loopMs - 120));\n    }\n\n\n\n    // Mario Overworld Score: [Pitch, 16th_note_units, BassPitch]\n    const MARIO_THEME = [\n      // Intro\n      [N.E5, 1, N.D4], [N.E5, 1, N.D4], [N.R, 1, N.R], [N.E5, 1, N.D4],\n      [N.R, 1, N.R], [N.C5, 1, N.D4], [N.E5, 2, N.D4],\n      [N.G5, 2, N.G3], [N.R, 2, N.R], [N.G4, 2, N.G3], [N.R, 2, N.R],\n\n      // Section A\n      [N.C5, 2, N.G3], [N.R, 1, N.R], [N.G4, 2, N.E3], [N.R, 1, N.R],\n      [N.E4, 2, N.C3], [N.R, 1, N.R], [N.A4, 2, N.F3], [N.B4, 2, N.G3],\n      [N.AS4, 1, N.FS3], [N.A4, 2, N.F3],\n      [N.G4, 1.5, N.E3], [N.E5, 1.5, N.C4], [N.G5, 1.5, N.E4], [N.A5, 2, N.F4],\n      [N.F5, 1, N.D4], [N.G5, 2, N.E4], [N.R, 1, N.R], [N.E5, 2, N.C4],\n      [N.C5, 1, N.A3], [N.D5, 1, N.B3], [N.B4, 2, N.G3], [N.R, 1, N.R],\n\n      // Section A Repeat\n      [N.C5, 2, N.G3], [N.R, 1, N.R], [N.G4, 2, N.E3], [N.R, 1, N.R],\n      [N.E4, 2, N.C3], [N.R, 1, N.R], [N.A4, 2, N.F3], [N.B4, 2, N.G3],\n      [N.AS4, 1, N.FS3], [N.A4, 2, N.F3],\n      [N.G4, 1.5, N.E3], [N.E5, 1.5, N.C4], [N.G5, 1.5, N.E4], [N.A5, 2, N.F4],\n      [N.F5, 1, N.D4], [N.G5, 2, N.E4], [N.R, 1, N.R], [N.E5, 2, N.C4],\n      [N.C5, 1, N.A3], [N.D5, 1, N.B3], [N.B4, 2, N.G3], [N.R, 2, N.R],\n\n      // Section B\n      [N.R, 2, N.R], [N.G5, 1, N.C4], [N.FS5, 1, N.B3], [N.F5, 1, N.AS3],\n      [N.DS5, 2, N.A3], [N.E5, 2, N.GS3], [N.R, 1, N.R],\n      [N.GS4, 1, N.C3], [N.A4, 1, N.E3], [N.C5, 2, N.A3],\n      [N.A4, 1, N.C3], [N.C5, 1, N.E3], [N.D5, 2, N.A3],\n      [N.R, 2, N.R], [N.G5, 1, N.C4], [N.FS5, 1, N.B3], [N.F5, 1, N.AS3],\n      [N.DS5, 2, N.A3], [N.E5, 2, N.GS3], [N.R, 1, N.R],\n      [N.C6, 2, N.C4], [N.C6, 1, N.C4], [N.C6, 3, N.C4],\n\n      // Section B Part 2\n      [N.R, 2, N.R], [N.G5, 1, N.C4], [N.FS5, 1, N.B3], [N.F5, 1, N.AS3],\n      [N.DS5, 2, N.A3], [N.E5, 2, N.GS3], [N.R, 1, N.R],\n      [N.GS4, 1, N.C3], [N.A4, 1, N.E3], [N.C5, 2, N.A3],\n      [N.A4, 1, N.C3], [N.C5, 1, N.E3], [N.D5, 2, N.A3],\n      [N.R, 2, N.R], [N.DS5, 3, N.AS3], [N.D5, 3, N.GS3], [N.C5, 4, N.G3],\n      [N.R, 2, N.R]\n    ];\n\n    function startMarioBGM() {\n      if (isBgmPlaying) return;\n      isBgmPlaying = true;\n      scheduleMarioTheme(0);\n    }\n\n    function stopMarioBGM() {\n      isBgmPlaying = false;\n      if (bgmTimeoutId) {\n        clearTimeout(bgmTimeoutId);\n        bgmTimeoutId = null;\n      }\n    }\n\n    function scheduleMarioTheme(startIndex) {\n      if (!isBgmPlaying || gameState !== 'PLAYING') {\n        isBgmPlaying = false;\n        return;\n      }\n\n      const ctx = getAudio();\n      if (ctx.state === 'suspended') {\n        ctx.resume();\n      }\n\n      // Tempo: ~105ms per 16th unit\n      const unitTime = 0.11;\n      let scheduleAheadTime = ctx.currentTime + 0.05;\n\n      for (let i = 0; i < MARIO_THEME.length; i++) {\n        const [leadFreq, units, bassFreq] = MARIO_THEME[i];\n        const duration = units * unitTime;\n\n        if (!isBgmMuted) {\n          // 1. Lead Melody Note (Square Wave Chiptune)\n          if (leadFreq > 0) {\n            const osc = ctx.createOscillator();\n            const gain = ctx.createGain();\n            osc.type = 'square';\n            osc.frequency.setValueAtTime(leadFreq, scheduleAheadTime);\n\n            gain.gain.setValueAtTime(0.08, scheduleAheadTime);\n            gain.gain.exponentialRampToValueAtTime(0.001, scheduleAheadTime + duration * 0.92);\n\n            osc.connect(gain);\n            gain.connect(ctx.destination);\n            osc.start(scheduleAheadTime);\n            osc.stop(scheduleAheadTime + duration * 0.95);\n          }\n\n          // 2. Bass Note (Warm Triangle Wave)\n          if (bassFreq > 0) {\n            const bassOsc = ctx.createOscillator();\n            const bassGain = ctx.createGain();\n            bassOsc.type = 'triangle';\n            bassOsc.frequency.setValueAtTime(bassFreq, scheduleAheadTime);\n\n            bassGain.gain.setValueAtTime(0.12, scheduleAheadTime);\n            bassGain.gain.exponentialRampToValueAtTime(0.001, scheduleAheadTime + duration * 0.88);\n\n            bassOsc.connect(bassGain);\n            bassGain.connect(ctx.destination);\n            bassOsc.start(scheduleAheadTime);\n            bassOsc.stop(scheduleAheadTime + duration * 0.9);\n          }\n        }\n\n        scheduleAheadTime += duration;\n      }\n\n      // Calculate total loop duration in milliseconds and loop seamlessly\n      const totalLoopMs = (scheduleAheadTime - ctx.currentTime) * 1000;\n      bgmTimeoutId = setTimeout(() => {\n        if (isBgmPlaying && gameState === 'PLAYING') {\n          scheduleMarioTheme(0);\n        }\n      }, Math.max(100, totalLoopMs - 150));\n    }\n\n    // Audio Synthesizer\n    let audioCtx = null;\n    function getAudio() {\n      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n      return audioCtx;\n    }\n\n    function playSound(type) {\n      try {\n        const ctx = getAudio();\n        const osc = ctx.createOscillator();\n        const gain = ctx.createGain();\n        osc.connect(gain);\n        gain.connect(ctx.destination);\n        const now = ctx.currentTime;\n\n        if (type === 'jump') {\n          osc.type = 'square';\n          osc.frequency.setValueAtTime(160, now);\n          osc.frequency.exponentialRampToValueAtTime(700, now + 0.16);\n          gain.gain.setValueAtTime(0.18, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.16);\n          osc.start(now);\n          osc.stop(now + 0.16);\n        } else if (type === 'coin') {\n          osc.type = 'sine';\n          osc.frequency.setValueAtTime(987.77, now);\n          osc.frequency.setValueAtTime(1318.51, now + 0.08);\n          gain.gain.setValueAtTime(0.2, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.35);\n          osc.start(now);\n          osc.stop(now + 0.35);\n        } else if (type === 'stomp') {\n          osc.type = 'triangle';\n          osc.frequency.setValueAtTime(260, now);\n          osc.frequency.exponentialRampToValueAtTime(60, now + 0.1);\n          gain.gain.setValueAtTime(0.3, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);\n          osc.start(now);\n          osc.stop(now + 0.1);\n        } else if (type === 'bump') {\n          osc.type = 'triangle';\n          osc.frequency.setValueAtTime(130, now);\n          osc.frequency.exponentialRampToValueAtTime(60, now + 0.08);\n          gain.gain.setValueAtTime(0.2, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.08);\n          osc.start(now);\n          osc.stop(now + 0.08);\n        } else if (type === 'powerup') {\n          const notes = [330, 392, 659, 523, 587, 784];\n          notes.forEach((freq, idx) => {\n            const o = ctx.createOscillator();\n            const g = ctx.createGain();\n            o.connect(g);\n            g.connect(ctx.destination);\n            o.frequency.setValueAtTime(freq, now + idx * 0.06);\n            g.gain.setValueAtTime(0.15, now + idx * 0.06);\n            g.gain.exponentialRampToValueAtTime(0.01, now + (idx + 1) * 0.06);\n            o.start(now + idx * 0.06);\n            o.stop(now + (idx + 1) * 0.06);\n          });\n        } else if (type === 'skid') {\n          osc.type = 'sawtooth';\n          osc.frequency.setValueAtTime(800, now);\n          osc.frequency.linearRampToValueAtTime(300, now + 0.09);\n          gain.gain.setValueAtTime(0.08, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.09);\n          osc.start(now);\n          osc.stop(now + 0.09);\n        } else if (type === 'kick') {\n          osc.type = 'triangle';\n          osc.frequency.setValueAtTime(320, now);\n          osc.frequency.exponentialRampToValueAtTime(80, now + 0.12);\n          gain.gain.setValueAtTime(0.35, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.12);\n          osc.start(now);\n          osc.stop(now + 0.12);\n        } else if (type === 'fireball') {\n          osc.type = 'sine';\n          osc.frequency.setValueAtTime(600, now);\n          osc.frequency.exponentialRampToValueAtTime(140, now + 0.14);\n          gain.gain.setValueAtTime(0.25, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.14);\n          osc.start(now);\n          osc.stop(now + 0.14);\n        } else if (type === 'firework') {\n          osc.type = 'square';\n          osc.frequency.setValueAtTime(150, now);\n          osc.frequency.exponentialRampToValueAtTime(40, now + 0.25);\n          gain.gain.setValueAtTime(0.35, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);\n          osc.start(now);\n          osc.stop(now + 0.25);\n        } else if (type === 'gameover') {\n          const notes = [400, 350, 300, 200];\n          notes.forEach((freq, idx) => {\n            const o = ctx.createOscillator();\n            const g = ctx.createGain();\n            o.connect(g);\n            g.connect(ctx.destination);\n            o.type = 'triangle';\n            o.frequency.setValueAtTime(freq, now + idx * 0.12);\n            g.gain.setValueAtTime(0.2, now + idx * 0.12);\n            g.gain.exponentialRampToValueAtTime(0.01, now + (idx + 1) * 0.12);\n            o.start(now + idx * 0.12);\n            o.stop(now + (idx + 1) * 0.12);\n          });\n        }\n      } catch (e) {}\n    }\n\n    // ==================== THREE.JS SETUP ====================\n    const canvas = document.getElementById('c');\n    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });\n    renderer.setSize(window.innerWidth, window.innerHeight);\n    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n    renderer.shadowMap.enabled = true;\n    renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n    renderer.toneMapping = THREE.ACESFilmicToneMapping;\n    renderer.toneMappingExposure = 1.15;\n\n    const scene = new THREE.Scene();\n    scene.background = new THREE.Color(0x60a5fa);\n    scene.fog = new THREE.Fog(0x60a5fa, 35, 95);\n\n    const camera = new THREE.PerspectiveCamera(46, window.innerWidth / window.innerHeight, 0.1, 1000);\n    camera.position.set(0, 6, 17);\n\n    window.addEventListener('resize', () => {\n      camera.aspect = window.innerWidth / window.innerHeight;\n      camera.updateProjectionMatrix();\n      renderer.setSize(window.innerWidth, window.innerHeight);\n    });\n\n    // Dynamic Lighting\n    const hemiLight = new THREE.HemisphereLight(0xffffff, 0x334155, 0.75);\n    hemiLight.position.set(0, 50, 0);\n    scene.add(hemiLight);\n\n    const dirLight = new THREE.DirectionalLight(0xfffaed, 1.3);\n    dirLight.position.set(25, 45, 30);\n    dirLight.castShadow = true;\n    dirLight.shadow.mapSize.width = 2048;\n    dirLight.shadow.mapSize.height = 2048;\n    dirLight.shadow.camera.near = 0.5;\n    dirLight.shadow.camera.far = 120;\n    dirLight.shadow.camera.left = -30;\n    dirLight.shadow.camera.right = 30;\n    dirLight.shadow.camera.top = 30;\n    dirLight.shadow.camera.bottom = -30;\n    dirLight.shadow.bias = -0.0005;\n    scene.add(dirLight);\n\n    // ==================== TEXTURES & MATERIALS ====================\n    // Dynamic Canvas Texture for Mario Cap \"M\" Badge\n    function createMarioBadgeTexture() {\n      const tc = document.createElement('canvas');\n      tc.width = 128;\n      tc.height = 128;\n      const tctx = tc.getContext('2d');\n      // White circle badge\n      tctx.fillStyle = '#ffffff';\n      tctx.beginPath();\n      tctx.arc(64, 64, 58, 0, Math.PI * 2);\n      tctx.fill();\n      tctx.strokeStyle = '#e2e8f0';\n      tctx.lineWidth = 4;\n      tctx.stroke();\n      // Red \"M\"\n      tctx.fillStyle = '#dc2626';\n      tctx.font = 'bold 76px \"Press Start 2P\", sans-serif';\n      tctx.textAlign = 'center';\n      tctx.textBaseline = 'middle';\n      tctx.fillText('M', 64, 68);\n      return new THREE.CanvasTexture(tc);\n    }\n\n    // Dynamic Question Mark Texture\n    function createQuestionBlockTexture() {\n      const tc = document.createElement('canvas');\n      tc.width = 128;\n      tc.height = 128;\n      const tctx = tc.getContext('2d');\n      // Gold background with metallic beveled border\n      tctx.fillStyle = '#f59e0b';\n      tctx.fillRect(0, 0, 128, 128);\n      tctx.fillStyle = '#fef08a';\n      tctx.fillRect(8, 8, 112, 10);\n      tctx.fillRect(8, 8, 10, 112);\n      tctx.fillStyle = '#78350f';\n      tctx.fillRect(8, 110, 112, 10);\n      tctx.fillRect(110, 8, 10, 112);\n      // Screws in corners\n      tctx.fillStyle = '#78350f';\n      tctx.fillRect(16, 16, 8, 8);\n      tctx.fillRect(104, 16, 8, 8);\n      tctx.fillRect(16, 104, 8, 8);\n      tctx.fillRect(104, 104, 8, 8);\n      // White/Black Question Mark\n      tctx.font = 'bold 74px \"Press Start 2P\", cursive';\n      tctx.textAlign = 'center';\n      tctx.textBaseline = 'middle';\n      tctx.fillStyle = '#000';\n      tctx.fillText('?', 66, 66);\n      tctx.fillStyle = '#ffffff';\n      tctx.fillText('?', 64, 64);\n      return new THREE.CanvasTexture(tc);\n    }\n\n    // Dynamic Brick Texture\n    function createBrickTexture() {\n      const tc = document.createElement('canvas');\n      tc.width = 128;\n      tc.height = 128;\n      const tctx = tc.getContext('2d');\n      tctx.fillStyle = '#991b1b';\n      tctx.fillRect(0, 0, 128, 128);\n      tctx.fillStyle = '#dc2626';\n      // Bricks row 1\n      tctx.fillRect(4, 4, 56, 26);\n      tctx.fillRect(68, 4, 56, 26);\n      // Bricks row 2\n      tctx.fillRect(4, 36, 26, 26);\n      tctx.fillRect(36, 36, 56, 26);\n      tctx.fillRect(98, 36, 26, 26);\n      // Bricks row 3\n      tctx.fillRect(4, 68, 56, 26);\n      tctx.fillRect(68, 68, 56, 26);\n      // Bricks row 4\n      tctx.fillRect(4, 100, 26, 24);\n      tctx.fillRect(36, 100, 56, 24);\n      tctx.fillRect(98, 100, 26, 24);\n      return new THREE.CanvasTexture(tc);\n    }\n\n    const badgeTex = createMarioBadgeTexture();\n    const questionTex = createQuestionBlockTexture();\n    const brickTex = createBrickTexture();\n\n    const mats = {\n      ground: new THREE.MeshStandardMaterial({ color: 0x9a3412, roughness: 0.85 }),\n      grass: new THREE.MeshStandardMaterial({ color: 0x22c55e, roughness: 0.6 }),\n      brick: new THREE.MeshStandardMaterial({ map: brickTex, roughness: 0.7, metalness: 0.1 }),\n      question: new THREE.MeshStandardMaterial({ map: questionTex, roughness: 0.3, metalness: 0.2 }),\n      questionEmpty: new THREE.MeshStandardMaterial({ color: 0x78350f, roughness: 0.9 }),\n      pipe: new THREE.MeshStandardMaterial({ color: 0x16a34a, roughness: 0.35, metalness: 0.15 }),\n      coin: new THREE.MeshStandardMaterial({ color: 0xfacc15, metalness: 0.95, roughness: 0.15, emissive: 0xf59e0b, emissiveIntensity: 0.4 }),\n      castle: new THREE.MeshStandardMaterial({ color: 0x64748b, roughness: 0.8 }),\n      flag: new THREE.MeshStandardMaterial({ color: 0x22c55e, roughness: 0.4 }),\n      cloud: new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95 }),\n    };\n\n    // ==================== REAL AUTHENTIC 3D MARIO ====================\n    function createRealMarioMesh() {\n      const g = new THREE.Group();\n\n      const redMat = new THREE.MeshStandardMaterial({ color: 0xdc2626, roughness: 0.5 }); // Shirt & Cap\n      const blueMat = new THREE.MeshStandardMaterial({ color: 0x1d4ed8, roughness: 0.6 }); // Denim Overalls\n      const skinMat = new THREE.MeshStandardMaterial({ color: 0xfecba1, roughness: 0.65 }); // Face & Neck\n      const bootMat = new THREE.MeshStandardMaterial({ color: 0x5c2e0b, roughness: 0.75 }); // Work Boots\n      const gloveMat = new THREE.MeshStandardMaterial({ color: 0xf8fafc, roughness: 0.5 }); // White Gloves\n      const mustacheMat = new THREE.MeshStandardMaterial({ color: 0x3d1d07, roughness: 0.8 }); // Mustache & Hair\n      const buttonMat = new THREE.MeshStandardMaterial({ color: 0xfbbf24, metalness: 0.9, roughness: 0.2 }); // Gold Buttons\n\n      // 1. Lower Body (Dungarees & Hips)\n      const hips = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.35, 0.45, 16), blueMat);\n      hips.position.y = 0.48;\n      hips.castShadow = true;\n      g.add(hips);\n\n      // 2. Chest (Red Shirt with Overalls Bib)\n      const chest = new THREE.Mesh(new THREE.SphereGeometry(0.42, 16, 16), redMat);\n      chest.position.y = 0.85;\n      chest.scale.set(1, 0.9, 0.85);\n      chest.castShadow = true;\n      g.add(chest);\n\n      // Dungarees Front Bib\n      const bib = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.42, 0.25), blueMat);\n      bib.position.set(0, 0.82, 0.28);\n      bib.castShadow = true;\n      g.add(bib);\n\n      // Shoulder Straps\n      const strapL = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.45, 0.48), blueMat);\n      strapL.position.set(-0.24, 0.9, 0.05);\n      strapL.rotation.z = -0.15;\n      const strapR = strapL.clone();\n      strapR.position.set(0.24, 0.9, 0.05);\n      strapR.rotation.z = 0.15;\n      g.add(strapL, strapR);\n\n      // Yellow Brass Buttons\n      const btn1 = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.05, 12), buttonMat);\n      btn1.rotation.x = Math.PI / 2;\n      btn1.position.set(-0.2, 0.88, 0.4);\n      const btn2 = btn1.clone();\n      btn2.position.set(0.2, 0.88, 0.4);\n      g.add(btn1, btn2);\n\n      // 3. Head & Face Group\n      const headGroup = new THREE.Group();\n      headGroup.position.y = 1.35;\n\n      // Chubby Peach Head\n      const head = new THREE.Mesh(new THREE.SphereGeometry(0.38, 20, 20), skinMat);\n      head.scale.set(1.05, 1, 0.95);\n      head.castShadow = true;\n      headGroup.add(head);\n\n      // Big Bulbous Mario Nose\n      const nose = new THREE.Mesh(new THREE.SphereGeometry(0.17, 16, 16), skinMat);\n      nose.position.set(0, -0.02, 0.38);\n      nose.scale.set(1.15, 1, 1);\n      nose.castShadow = true;\n      headGroup.add(nose);\n\n      // Iconic Curved Mustache (Swooped shape)\n      const mustacheG = new THREE.Group();\n      const stacheCenter = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 12), mustacheMat);\n      stacheCenter.scale.set(1.6, 0.7, 0.8);\n      stacheCenter.position.set(0, -0.12, 0.38);\n      mustacheG.add(stacheCenter);\n      // Left curl\n      const curlL = new THREE.Mesh(new THREE.SphereGeometry(0.12, 10, 10), mustacheMat);\n      curlL.position.set(-0.2, -0.14, 0.35);\n      curlL.scale.set(1.2, 0.8, 0.8);\n      // Right curl\n      const curlR = curlL.clone();\n      curlR.position.set(0.2, -0.14, 0.35);\n      mustacheG.add(curlL, curlR);\n      headGroup.add(mustacheG);\n\n      // Eyes (Blue Cartoon Eyes with Specular Highlights)\n      function makeEye(isRight) {\n        const eyeG = new THREE.Group();\n        // White sclera\n        const sclera = new THREE.Mesh(new THREE.SphereGeometry(0.08, 12, 12), new THREE.MeshBasicMaterial({ color: 0xffffff }));\n        sclera.scale.set(0.7, 1.2, 0.3);\n        eyeG.add(sclera);\n        // Blue Iris\n        const iris = new THREE.Mesh(new THREE.SphereGeometry(0.05, 10, 10), new THREE.MeshBasicMaterial({ color: 0x0284c7 }));\n        iris.scale.set(0.8, 1.1, 0.3);\n        iris.position.set(0, 0, 0.03);\n        eyeG.add(iris);\n        // Black Pupil\n        const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.03, 8, 8), new THREE.MeshBasicMaterial({ color: 0x000000 }));\n        pupil.position.set(0, 0, 0.05);\n        eyeG.add(pupil);\n        // Catchlight gleam\n        const gleam = new THREE.Mesh(new THREE.SphereGeometry(0.015, 6, 6), new THREE.MeshBasicMaterial({ color: 0xffffff }));\n        gleam.position.set(0.01, 0.02, 0.06);\n        eyeG.add(gleam);\n        return eyeG;\n      }\n\n      const eyeL = makeEye(false);\n      eyeL.position.set(-0.13, 0.1, 0.33);\n      const eyeR = makeEye(true);\n      eyeR.position.set(0.13, 0.1, 0.33);\n      headGroup.add(eyeL, eyeR);\n\n      // Arched Eyebrows\n      const browL = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.04, 0.05), mustacheMat);\n      browL.position.set(-0.14, 0.22, 0.34);\n      browL.rotation.z = -0.15;\n      const browR = browL.clone();\n      browR.position.set(0.14, 0.22, 0.34);\n      browR.rotation.z = 0.15;\n      headGroup.add(browL, browR);\n\n      // Ears\n      const earL = new THREE.Mesh(new THREE.SphereGeometry(0.1, 10, 10), skinMat);\n      earL.position.set(-0.4, 0, 0.05);\n      earL.scale.set(0.5, 1, 0.8);\n      const earR = earL.clone();\n      earR.position.set(0.4, 0, 0.05);\n      headGroup.add(earL, earR);\n\n      // 4. Iconic Mario Cap with Curved Visor & \"M\" Badge\n      const capDome = new THREE.Mesh(new THREE.SphereGeometry(0.44, 20, 20), redMat);\n      capDome.position.set(0, 0.16, -0.05);\n      capDome.scale.set(1.08, 0.85, 1.15);\n      headGroup.add(capDome);\n\n      // Front Curved Visor Brim\n      const visor = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.08, 20, 1, false, 0, Math.PI), redMat);\n      visor.rotation.x = Math.PI / 2.3;\n      visor.position.set(0, 0.12, 0.26);\n      headGroup.add(visor);\n\n      // White Badge with Red \"M\"\n      const badgeMat = new THREE.MeshStandardMaterial({ map: badgeTex, roughness: 0.4 });\n      const badgeMesh = new THREE.Mesh(new THREE.CircleGeometry(0.14, 16), badgeMat);\n      badgeMesh.position.set(0, 0.32, 0.36);\n      badgeMesh.rotation.x = -0.2;\n      headGroup.add(badgeMesh);\n\n      // Hair in Back and Sideburns\n      const hairBack = new THREE.Mesh(new THREE.SphereGeometry(0.38, 16, 16), mustacheMat);\n      hairBack.position.set(0, -0.08, -0.18);\n      hairBack.scale.set(1, 0.8, 0.9);\n      headGroup.add(hairBack);\n\n      g.add(headGroup);\n\n      // 5. Arms with White Cartoon Gloves\n      function makeArm(isLeft) {\n        const armG = new THREE.Group();\n        // Red Sleeve\n        const sleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.11, 0.42, 12), redMat);\n        sleeve.position.y = -0.21;\n        sleeve.castShadow = true;\n        armG.add(sleeve);\n        // Glove Cuff\n        const cuff = new THREE.Mesh(new THREE.TorusGeometry(0.12, 0.04, 8, 16), gloveMat);\n        cuff.position.y = -0.42;\n        cuff.rotation.x = Math.PI / 2;\n        armG.add(cuff);\n        // White Glove Hand\n        const hand = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 12), gloveMat);\n        hand.position.y = -0.52;\n        hand.castShadow = true;\n        armG.add(hand);\n        return armG;\n      }\n\n      const leftArm = makeArm(true);\n      leftArm.position.set(-0.48, 0.95, 0);\n      const rightArm = makeArm(false);\n      rightArm.position.set(0.48, 0.95, 0);\n      g.add(leftArm, rightArm);\n\n      // 6. Legs & Brown Work Boots\n      function makeLeg(isLeft) {\n        const legG = new THREE.Group();\n        // Blue Pant Leg\n        const pants = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.14, 0.36, 12), blueMat);\n        pants.position.y = -0.18;\n        pants.castShadow = true;\n        legG.add(pants);\n        // Work Boot\n        const bootG = new THREE.Group();\n        const foot = new THREE.Mesh(new THREE.SphereGeometry(0.18, 12, 12), bootMat);\n        foot.position.set(0, -0.32, 0.08);\n        foot.scale.set(0.9, 0.7, 1.4);\n        foot.castShadow = true;\n        bootG.add(foot);\n        // Sole\n        const sole = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.06, 0.44), mustacheMat);\n        sole.position.set(0, -0.42, 0.08);\n        bootG.add(sole);\n        legG.add(bootG);\n        return legG;\n      }\n\n      const leftLeg = makeLeg(true);\n      leftLeg.position.set(-0.2, 0.38, 0);\n      const rightLeg = makeLeg(false);\n      rightLeg.position.set(0.2, 0.38, 0);\n      g.add(leftLeg, rightLeg);\n\n      g.userData = { leftArm, rightArm, leftLeg, rightLeg, headGroup, redMat, blueMat, capDome, visor };\n      return g;\n    }\n\n    // 3D Goomba Builder\n    function createGoombaMesh() {\n      const g = new THREE.Group();\n      const capMat = new THREE.MeshStandardMaterial({ color: 0x9a3412, roughness: 0.6 });\n      const stemMat = new THREE.MeshStandardMaterial({ color: 0xfed7aa, roughness: 0.5 });\n      const footMat = new THREE.MeshStandardMaterial({ color: 0x1c1917, roughness: 0.8 });\n\n      // Cap\n      const cap = new THREE.Mesh(new THREE.ConeGeometry(0.5, 0.46, 16), capMat);\n      cap.position.y = 0.56;\n      cap.scale.set(1.1, 1, 1.1);\n      cap.castShadow = true;\n      g.add(cap);\n\n      // Face Stem\n      const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.22, 0.36, 16), stemMat);\n      stem.position.y = 0.28;\n      stem.castShadow = true;\n      g.add(stem);\n\n      // Angry Eyes\n      const eyeMat = new THREE.MeshBasicMaterial({ color: 0x000000 });\n      const e1 = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.12, 0.08), eyeMat);\n      e1.position.set(-0.1, 0.32, 0.26);\n      e1.rotation.z = -0.25;\n      const e2 = e1.clone();\n      e2.position.set(0.1, 0.32, 0.26);\n      e2.rotation.z = 0.25;\n      g.add(e1, e2);\n\n      // Feet\n      const foot1 = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.32), footMat);\n      foot1.position.set(-0.16, 0.06, 0.06);\n      foot1.castShadow = true;\n      const foot2 = foot1.clone();\n      foot2.position.set(0.16, 0.06, 0.06);\n      g.add(foot1, foot2);\n\n      g.userData = { foot1, foot2, cap };\n      return g;\n    }\n\n    // 3D Koopa Builder\n    function createKoopaMesh() {\n      const g = new THREE.Group();\n      const shellMat = new THREE.MeshStandardMaterial({ color: 0x16a34a, roughness: 0.4 });\n      const bellyMat = new THREE.MeshStandardMaterial({ color: 0xfef08a, roughness: 0.5 });\n      const skinMat = new THREE.MeshStandardMaterial({ color: 0xfacc15, roughness: 0.5 });\n      const shoeMat = new THREE.MeshStandardMaterial({ color: 0xb45309, roughness: 0.8 });\n\n      const shell = new THREE.Mesh(new THREE.SphereGeometry(0.44, 16, 16), shellMat);\n      shell.position.y = 0.58;\n      shell.scale.set(0.85, 1, 1);\n      shell.castShadow = true;\n      g.add(shell);\n\n      const belly = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.42, 16), bellyMat);\n      belly.position.set(0, 0.52, 0.15);\n      g.add(belly);\n\n      const head = new THREE.Mesh(new THREE.SphereGeometry(0.24, 12, 12), skinMat);\n      head.position.set(0, 0.88, 0.26);\n      head.castShadow = true;\n      g.add(head);\n\n      const s1 = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.12, 0.36), shoeMat);\n      s1.position.set(-0.18, 0.06, 0.06);\n      const s2 = s1.clone();\n      s2.position.set(0.18, 0.06, 0.06);\n      g.add(s1, s2);\n\n      g.userData = { shell, belly, head, s1, s2 };\n      return g;\n    }\n\n    // 3D Level Data\n    const LEVEL_WIDTH = 210;\n    const LEVEL_HEIGHT = 18;\n    let levelGrid = [];\n    const tileMeshes = new Map();\n    let enemies = [];\n    let items = [];\n    let clouds3D = [];\n    let particles3D = [];\n\n    const mario3D = createRealMarioMesh();\n    scene.add(mario3D);\n\n    const mario = {\n      x: 3,\n      y: 2,\n      vx: 0,\n      vy: 0,\n      w: 0.7,\n      h: 1.6,\n      isGrounded: false,\n      isBig: false,\n      isFire: false,\n      isStar: false,\n      starTimer: 0,\n      facing: 'right',\n      invulnerableTimer: 0,\n    };\n\n    let score = 0;\n    let coins = 0;\n    let lives = 3;\n    let timeLeft = 400;\n    let gameState = 'START';\n    let globalTicks = 0;\n    let timerInterval = null;\n\n    const keys = { left: false, right: false, jump: false, fire: false };\n\n    function build3DLevel() {\n      tileMeshes.forEach(mesh => scene.remove(mesh));\n      tileMeshes.clear();\n      enemies.forEach(e => scene.remove(e.mesh));\n      enemies = [];\n      items.forEach(i => scene.remove(i.mesh));\n      items = [];\n      clouds3D.forEach(c => scene.remove(c));\n      clouds3D = [];\n\n      levelGrid = Array.from({ length: LEVEL_HEIGHT }, () => Array(LEVEL_WIDTH).fill(0));\n\n      // Continuous Ground with clearly spaced pits that are easy to jump\n      for (let x = 0; x < LEVEL_WIDTH; x++) {\n        if ((x >= 69 && x <= 71) || (x >= 86 && x <= 88) || (x >= 153 && x <= 155)) continue;\n        levelGrid[0][x] = 1;\n        levelGrid[1][x] = 1;\n      }\n\n      function addCoinArc(centerX, centerY, radius, count) {\n        for (let i = 0; i < count; i++) {\n          const angle = Math.PI * (0.2 + 0.6 * (i / (count - 1)));\n          const cx = centerX - Math.cos(angle) * radius;\n          const cy = centerY + Math.sin(angle) * (radius * 0.75);\n          spawnFloatingCoin3D(cx, cy);\n        }\n      }\n\n      // ==================== BALANCED COINS & BLOCKS ====================\n      // Zone 1: Opening Runway\n      spawnFloatingCoin3D(7.5, 2.7);\n      levelGrid[5][9] = 3;  // ? Coin\n      levelGrid[5][10] = 2; // Brick\n      levelGrid[5][11] = 4; // ? Super Mushroom!\n      levelGrid[5][12] = 2; // Brick\n      levelGrid[5][13] = 3; // ? Coin\n      levelGrid[9][11] = 3; // High ? Coin\n      spawnFloatingCoin3D(11.5, 6.3);\n\n      // Zone 2: Classic Blocks\n      levelGrid[5][16] = 3; // ? Coin\n      levelGrid[5][18] = 2; // Brick\n      levelGrid[5][20] = 2; // Brick\n      levelGrid[5][21] = 4; // ? Super Mushroom!\n      levelGrid[5][22] = 2; // Brick\n      levelGrid[5][24] = 2; // Brick\n      levelGrid[5][25] = 3; // ? Coin\n      \n      levelGrid[9][21] = 3; // High ? Coin\n      levelGrid[9][22] = 2; // Brick\n      levelGrid[9][23] = 3; // High ? Coin\n      spawnFloatingCoin3D(21.5, 6.3);\n      spawnFloatingCoin3D(22.5, 10.3);\n\n      // Zone 3: Pipes & Coin Arcs\n      buildPipe3D(28, 2, 2);\n      addCoinArc(28.5, 4.2, 1.8, 3); // 3-coin arc\n\n      // Floating Bridge between Pipe 1 & 2\n      levelGrid[5][32] = 3; // ? Coin\n      levelGrid[5][33] = 2; // Brick\n      levelGrid[5][34] = 3; // ? Coin\n      levelGrid[8][33] = 4; // High Mushroom ?\n      spawnFloatingCoin3D(33.5, 6.3);\n\n      buildPipe3D(38, 2, 2.5);\n      addCoinArc(38.5, 4.8, 1.9, 3);\n\n      // Stepped Formation between Pipe 2 & 3\n      levelGrid[4][42] = 3;\n      levelGrid[6][44] = 3;\n      levelGrid[8][46] = 4; // Mushroom\n      spawnFloatingCoin3D(44.5, 7.3);\n\n      buildPipe3D(48, 2, 3);\n      addCoinArc(48.5, 5.3, 2.0, 3);\n\n      // Block Fortress between Pipe 3 & 4\n      levelGrid[5][52] = 2;\n      levelGrid[5][53] = 3;\n      levelGrid[5][54] = 2;\n      levelGrid[9][53] = 3;\n      spawnFloatingCoin3D(53.5, 6.3);\n      spawnFloatingCoin3D(53.5, 10.3);\n\n      buildPipe3D(58, 2, 2.5);\n      addCoinArc(58.5, 4.8, 1.9, 3);\n\n      // Zone 4: Pyramid & Pit 1\n      for (let x = 62; x <= 66; x++) levelGrid[3][x] = 2;\n      levelGrid[4][64] = 3;\n      levelGrid[5][64] = 3;\n      spawnFloatingCoin3D(64.5, 6.3);\n\n      // Pit 1 Stepping Stone\n      levelGrid[4][70] = 3; // ? Coin over pit\n      spawnFloatingCoin3D(70.5, 5.5);\n\n      // Zone 5: Midfield Skyway\n      levelGrid[5][76] = 3;\n      levelGrid[5][78] = 2;\n      levelGrid[5][80] = 3;\n      levelGrid[5][82] = 2;\n      levelGrid[5][84] = 3;\n      \n      levelGrid[9][79] = 2;\n      levelGrid[9][80] = 3;\n      levelGrid[9][81] = 2;\n      spawnFloatingCoin3D(80.5, 10.3);\n\n      // Secret High Cloud Platform (y=12)\n      levelGrid[12][80] = 4; // Super Mushroom!\n      levelGrid[12][81] = 3;\n      spawnFloatingCoin3D(80.5, 13.3);\n      spawnFloatingCoin3D(81.5, 13.3);\n\n      // Pit 2 Stepping Stone\n      levelGrid[4][87] = 3;\n      spawnFloatingCoin3D(87.5, 5.5);\n\n      // Pipe 5\n      buildPipe3D(96, 2, 2.5);\n      addCoinArc(96.5, 4.8, 1.9, 3);\n\n      // Zone 6: Skyway & Pyramid\n      levelGrid[5][102] = 3;\n      levelGrid[5][105] = 2;\n      levelGrid[5][108] = 3;\n      levelGrid[8][105] = 3;\n      spawnFloatingCoin3D(105.5, 9.3);\n\n      for (let step = 1; step <= 4; step++) {\n        for (let r = 2; r < 2 + step; r++) levelGrid[r][117 + step] = 2;\n      }\n      for (let step = 1; step <= 4; step++) {\n        for (let r = 2; r < 2 + (5 - step); r++) levelGrid[r][121 + step] = 2;\n      }\n      levelGrid[7][121] = 3;\n      levelGrid[7][122] = 4; // Super Mushroom\n      spawnFloatingCoin3D(121.5, 8.3);\n\n      // Zone 7: Staircase & Pre-Flagpole\n      for (let step = 1; step <= 7; step++) {\n        for (let r = 2; r < 2 + step; r++) levelGrid[r][134 + step] = 1;\n      }\n      spawnFloatingCoin3D(138.5, 6.5);\n\n      for (let step = 1; step <= 7; step++) {\n        for (let r = 2; r < 2 + (8 - step); r++) levelGrid[r][143 + step] = 1;\n      }\n      spawnFloatingCoin3D(146.5, 5.5);\n\n      // Pit 3 Stepping Stone\n      levelGrid[5][154] = 3;\n      spawnFloatingCoin3D(154.5, 6.5);\n\n      // Bonus Sky Platform\n      levelGrid[6][162] = 3;\n      levelGrid[6][164] = 2;\n      levelGrid[6][166] = 3;\n      spawnFloatingCoin3D(164.5, 7.3);\n\n      // Final Staircase (x=175..182)\n      for (let step = 1; step <= 8; step++) {\n        for (let r = 2; r < 2 + step; r++) levelGrid[r][175 + step] = 1;\n      }\n      spawnFloatingCoin3D(177.5, 4.5);\n      spawnFloatingCoin3D(180.5, 7.5);\n      spawnFloatingCoin3D(182.5, 9.5); // Peak coin before flagpole jump!\n\n      // Flagpole at x=188\n      buildFlagpole3D(188, 2);\n      // Castle at x=196..202\n      buildCastle3D(199, 2);\n\n      // Render 3D Tile Meshes\n      const boxGeo = new THREE.BoxGeometry(1, 1, 1);\n\n      for (let y = 0; y < LEVEL_HEIGHT; y++) {\n        for (let x = 0; x < LEVEL_WIDTH; x++) {\n          const t = levelGrid[y][x];\n          if (t === 1) {\n            const m = new THREE.Mesh(boxGeo, y === 1 ? mats.grass : mats.ground);\n            m.position.set(x + 0.5, y + 0.5, 0);\n            m.receiveShadow = true;\n            m.castShadow = true;\n            scene.add(m);\n            tileMeshes.set(`${x},${y}`, m);\n          } else if (t === 2) {\n            const m = new THREE.Mesh(boxGeo, mats.brick);\n            m.position.set(x + 0.5, y + 0.5, 0);\n            m.receiveShadow = true;\n            m.castShadow = true;\n            scene.add(m);\n            tileMeshes.set(`${x},${y}`, m);\n          } else if (t === 3 || t === 4) {\n            const m = new THREE.Mesh(boxGeo, mats.question);\n            m.position.set(x + 0.5, y + 0.5, 0);\n            m.receiveShadow = true;\n            m.castShadow = true;\n            scene.add(m);\n            tileMeshes.set(`${x},${y}`, m);\n          }\n        }\n      }\n\n      // ==================== ENEMIES (+50% INCREASE: 13 TOTAL) ====================\n      spawnEnemy3D('goomba', 14, 2, -0.035);  // [NEW] Early Goomba\n      spawnEnemy3D('goomba', 22, 2, -0.035);  // Classic Goomba\n      spawnEnemy3D('goomba', 34, 2, -0.035);  // Between Pipe 1 & 2\n      spawnEnemy3D('goomba', 44, 2, -0.035);  // [NEW] Between Pipe 2 & 3\n      spawnEnemy3D('koopa', 53, 2, -0.04);    // Koopa near fortress\n      spawnEnemy3D('koopa', 65, 2, -0.04);    // [NEW] Koopa near Pyramid 1\n      spawnEnemy3D('goomba', 78, 2, -0.035);  // Skyway Goomba\n      spawnEnemy3D('goomba', 92, 2, -0.035);  // Post Pit 2 Goomba\n      spawnEnemy3D('koopa', 104, 2, -0.04);   // Koopa patrol\n      spawnEnemy3D('goomba', 120, 2, -0.035); // Pyramid Goomba\n      spawnEnemy3D('goomba', 140, 2, -0.035); // [NEW] Between Staircases\n      spawnEnemy3D('koopa', 165, 2, -0.04);   // Pre-Flagpole Koopa\n      spawnEnemy3D('goomba', 171, 2, -0.035); // [NEW] Final Staircase Defender\n\n      // Background 3D Clouds\n      for (let i = 0; i < LEVEL_WIDTH; i += 20) {\n        const cloud = createCloud3D();\n        cloud.position.set(i + Math.random() * 6, 11 + Math.random() * 5, -10 - Math.random() * 6);\n        scene.add(cloud);\n        clouds3D.push(cloud);\n      }\n    }\n\n    function buildPipe3D(x, baseY, height) {\n      const g = new THREE.Group();\n      const body = new THREE.Mesh(new THREE.CylinderGeometry(0.88, 0.88, height, 24), mats.pipe);\n      body.position.y = baseY + height / 2;\n      body.castShadow = true;\n      body.receiveShadow = true;\n      g.add(body);\n\n      const rim = new THREE.Mesh(new THREE.CylinderGeometry(1.02, 1.02, 0.6, 24), mats.pipe);\n      rim.position.y = baseY + height - 0.3;\n      rim.castShadow = true;\n      g.add(rim);\n\n      // Dark Hollow Inside\n      const hole = new THREE.Mesh(new THREE.CylinderGeometry(0.75, 0.75, 0.05, 16), new THREE.MeshBasicMaterial({ color: 0x052e16 }));\n      hole.position.y = baseY + height + 0.01;\n      g.add(hole);\n\n      g.position.x = x + 0.5;\n      scene.add(g);\n\n      // Register collision tiles\n      const hInt = Math.ceil(height);\n      for (let h = 0; h < hInt; h++) {\n        levelGrid[baseY + h][x] = 5;\n        levelGrid[baseY + h][x + 1] = 5;\n      }\n    }\n\n    function buildFlagpole3D(x, baseY) {\n      const g = new THREE.Group();\n      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 12, 16), new THREE.MeshStandardMaterial({ color: 0xf1f5f9, metalness: 0.8 }));\n      pole.position.set(x + 0.5, baseY + 6, 0);\n      pole.castShadow = true;\n      g.add(pole);\n\n      const ball = new THREE.Mesh(new THREE.SphereGeometry(0.32, 16, 16), mats.coin);\n      ball.position.set(x + 0.5, baseY + 12, 0);\n      g.add(ball);\n\n      const flag = new THREE.Mesh(new THREE.BoxGeometry(1.6, 1.0, 0.04), mats.flag);\n      flag.position.set(x - 0.3, baseY + 11, 0);\n      flag.castShadow = true;\n      g.add(flag);\n\n      scene.add(g);\n    }\n\n    function buildCastle3D(x, baseY) {\n      const g = new THREE.Group();\n      const base = new THREE.Mesh(new THREE.BoxGeometry(7, 4.5, 3.5), mats.castle);\n      base.position.set(x + 0.5, baseY + 2.25, -1);\n      base.castShadow = true;\n      g.add(base);\n\n      for (let i = -3; i <= 3; i += 2) {\n        const turret = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1.4, 1.2), mats.castle);\n        turret.position.set(x + 0.5 + i, baseY + 5.1, -1);\n        g.add(turret);\n      }\n\n      const door = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.9, 2.6, 16, 1, false, 0, Math.PI), new THREE.MeshBasicMaterial({ color: 0x000000 }));\n      door.rotation.z = Math.PI / 2;\n      door.position.set(x + 0.5, baseY + 1.3, 0.8);\n      g.add(door);\n\n      scene.add(g);\n    }\n\n    function createCloud3D() {\n      const g = new THREE.Group();\n      const geo = new THREE.SphereGeometry(1.4, 10, 10);\n      const s1 = new THREE.Mesh(geo, mats.cloud);\n      const s2 = new THREE.Mesh(geo, mats.cloud);\n      s2.position.set(1.5, 0.4, 0);\n      s2.scale.set(1.25, 1.25, 1.25);\n      const s3 = new THREE.Mesh(geo, mats.cloud);\n      s3.position.set(3.0, 0, 0);\n      g.add(s1, s2, s3);\n      return g;\n    }\n\n    function spawnEnemy3D(type, x, y, vx) {\n      const mesh = type === 'goomba' ? createGoombaMesh() : createKoopaMesh();\n      mesh.position.set(x + 0.5, y, 0);\n      scene.add(mesh);\n      enemies.push({ type, x: x + 0.5, y, vx, alive: true, flatTimer: 0, mesh, state: 'walking' });\n    }\n\n    let jumpHoldTicks = 0;\n\n    function startGame() {\n      hideAllOverlays();\n      getAudio();\n      score = 0;\n      coins = 0;\n      lives = 3;\n      timeLeft = 400;\n      mario.x = 3.5;\n      mario.y = 2.0;\n      mario.vx = 0;\n      mario.vy = 0;\n      mario.isBig = false;\n      mario.isFire = false;\n      mario.isStar = false;\n      mario.starTimer = 0;\n      mario.h = 1.6;\n      mario3D.scale.set(1, 1, 1);\n      recordedRunFrames = [];\n\n      mario3D.userData.redMat.color.setHex(0xdc2626);\n      mario3D.userData.blueMat.color.setHex(0x1d4ed8);\n      mario3D.userData.capDome.material = mario3D.userData.redMat;\n      mario3D.userData.visor.material = mario3D.userData.redMat;\n\n      fireballs.forEach(f => scene.remove(f.mesh));\n      fireballs = [];\n\n      if (!ghost3D) ghost3D = createGhostMarioMesh();\n      if (ghostReplay && ghostReplay.path && ghostReplay.path.length > 0) {\n        ghost3D.visible = true;\n      } else {\n        ghost3D.visible = false;\n      }\n\n      document.getElementById('starBadge').style.display = 'none';\n      build3DLevel();\n      gameState = 'PLAYING';\n      startMarioBGM();\n\n      if (timerInterval) clearInterval(timerInterval);\n      timerInterval = setInterval(() => {\n        if (gameState === 'PLAYING') {\n          timeLeft--;\n          document.getElementById('hudTime').innerText = String(timeLeft).padStart(3, '0');\n          if (timeLeft <= 0) killMario();\n        }\n      }, 1000);\n\n      requestAnimationFrame(gameLoop);\n    }\n\n    function update() {\n      if (gameState !== 'PLAYING') return;\n      globalTicks++;\n\n      // 1. Horizontal Input & Movement\n      const isSprinting = keys.fire;\n      const maxSpeed = isSprinting ? 0.22 : 0.14;\n      const accel = 0.015;\n      const friction = 0.82;\n\n      if (keys.left) {\n        mario.vx -= accel;\n        mario.facing = 'left';\n      } else if (keys.right) {\n        mario.vx += accel;\n        mario.facing = 'right';\n      } else {\n        mario.vx *= friction;\n        if (Math.abs(mario.vx) < 0.001) mario.vx = 0;\n      }\n\n      // Detect Skidding / Reversing Direction abruptly\n      if (mario.isGrounded) {\n        if ((keys.left && mario.vx > 0.08) || (keys.right && mario.vx < -0.08)) {\n          if (globalTicks % 4 === 0) {\n            spawnDust3D(mario.x + (mario.facing === 'left' ? 0.3 : -0.3), mario.y);\n            playSound('skid');\n          }\n        } else if (Math.abs(mario.vx) > 0.1 && globalTicks % 8 === 0) {\n          // Trailing running dust\n          spawnDust3D(mario.x + (mario.facing === 'left' ? 0.35 : -0.35), mario.y);\n        }\n      }\n\n      mario.vx = Math.max(-maxSpeed, Math.min(maxSpeed, mario.vx));\n\n      // 2. Variable Jump Physics (Hold to jump higher!)\n      if (keys.jump) {\n        if (mario.isGrounded) {\n          mario.vy = 0.36;\n          mario.isGrounded = false;\n          jumpHoldTicks = 12; // allow up to 12 sustained lift frames\n          playSound('jump');\n          spawnDust3D(mario.x, mario.y);\n        } else if (jumpHoldTicks > 0) {\n          mario.vy += 0.014; // sustained upward propulsion\n          jumpHoldTicks--;\n        }\n      } else {\n        jumpHoldTicks = 0;\n      }\n\n      // Gravity\n      mario.vy -= 0.022;\n      if (mario.vy < -0.42) mario.vy = -0.42;\n\n      // 3. Move X with Wall Collision (Never detects floor beneath feet!)\n      mario.x += mario.vx;\n      handleTileCollisionX();\n\n      // 4. Move Y with Floor / Ceiling Collision\n      const prevGrounded = mario.isGrounded;\n      const prevVy = mario.vy;\n      mario.y += mario.vy;\n      mario.isGrounded = false;\n      handleTileCollisionY();\n\n      // Detect Landing from fall\n      if (!prevGrounded && mario.isGrounded) {\n        if (prevVy < -0.22) {\n          triggerCamShake(0.12);\n          spawnDust3D(mario.x - 0.25, mario.y);\n          spawnDust3D(mario.x + 0.25, mario.y);\n          marioSquashY = 0.8;\n          marioSquashX = 1.2;\n        }\n      }\n\n      // Smooth squash-stretch restoration\n      marioSquashY += (1.0 - marioSquashY) * 0.2;\n      marioSquashX += (1.0 - marioSquashX) * 0.2;\n\n      // Bounds\n      if (mario.x < 1.0) mario.x = 1.0;\n      if (mario.y < -3.0) killMario();\n      if (mario.x >= 188 && gameState === 'PLAYING') victory();\n\n      // 5. Update Real 3D Mario Mesh & Realistic Skeletal Animation\n      mario3D.position.set(mario.x, mario.y, 0);\n\n      // Apply Dynamic Squash & Stretch\n      const baseScale = mario.isBig ? 1.35 : 1.0;\n      mario3D.scale.set(baseScale * marioSquashX, baseScale * marioSquashY, baseScale * marioSquashX);\n\n      // Smooth facing rotation & sprint leaning\n      const targetRotY = mario.facing === 'left' ? -Math.PI / 2 : Math.PI / 2;\n      mario3D.rotation.y += (targetRotY - mario3D.rotation.y) * 0.3;\n      mario3D.rotation.z = -mario.vx * 0.9;\n\n      const { leftArm, rightArm, leftLeg, rightLeg, headGroup } = mario3D.userData;\n      const speedNorm = Math.abs(mario.vx) / maxSpeed;\n\n      if (mario.isGrounded) {\n        if (speedNorm > 0.05) {\n          // Dynamic Running Stride Cycle\n          const runRate = globalTicks * 0.45 * (isSprinting ? 1.4 : 1.0);\n          const stride = Math.sin(runRate) * 0.85;\n          leftLeg.rotation.x = stride;\n          rightLeg.rotation.x = -stride;\n          leftArm.rotation.x = -stride * 0.9;\n          rightArm.rotation.x = stride * 0.9;\n          headGroup.position.y = 1.35 + Math.abs(Math.sin(runRate * 2)) * 0.06; // running head bob\n        } else {\n          // Gentle Breathing Idle\n          leftLeg.rotation.x = 0;\n          rightLeg.rotation.x = 0;\n          leftArm.rotation.x = Math.sin(globalTicks * 0.06) * 0.05;\n          rightArm.rotation.x = -Math.sin(globalTicks * 0.06) * 0.05;\n          headGroup.position.y = 1.35 + Math.sin(globalTicks * 0.08) * 0.02;\n        }\n      } else {\n        // Iconic Super Mario Jump Pose (fist raised high!)\n        leftArm.rotation.x = -1.5;\n        rightArm.rotation.x = 0.5;\n        leftLeg.rotation.x = 0.6;\n        rightLeg.rotation.x = -0.5;\n        headGroup.position.y = 1.37;\n      }\n\n      // 6. Update 3D Enemies\n      enemies.forEach(enemy => {\n        if (!enemy.alive) {\n          if (enemy.flatTimer > 0) {\n            enemy.flatTimer--;\n            if (enemy.flatTimer === 0) scene.remove(enemy.mesh);\n          }\n          return;\n        }\n\n        enemy.x += enemy.vx;\n\n        if (enemy.type === 'koopa' && enemy.state === 'sliding') {\n          enemy.mesh.rotation.y += 0.28;\n          const checkX = Math.floor(enemy.x + (enemy.vx > 0 ? 0.5 : -0.5));\n          const checkY = Math.floor(enemy.y + 0.5);\n          if (getTile(checkX, checkY) > 0) {\n            enemy.vx *= -1;\n            playSound('bump');\n            triggerCamShake(0.14);\n            spawnDust3D(enemy.x, enemy.y);\n          }\n\n          enemies.forEach(other => {\n            if (other !== enemy && other.alive) {\n              const dX = enemy.x - other.x;\n              const dY = enemy.y - other.y;\n              if (Math.abs(dX) < 0.85 && Math.abs(dY) < 0.9) {\n                other.alive = false;\n                scene.remove(other.mesh);\n                score += 400;\n                playSound('kick');\n                triggerCamShake(0.2);\n                spawnSparkles3D(other.x, other.y + 0.4, 12);\n                spawnFloatingText3D('+400!', other.x, other.y + 0.6, '#f43f5e');\n              }\n            }\n          });\n        } else {\n          const checkX = Math.floor(enemy.x + (enemy.vx > 0 ? 0.5 : -0.5));\n          const checkY = Math.floor(enemy.y + 0.5);\n          if (getTile(checkX, checkY) > 0) enemy.vx *= -1;\n        }\n\n        enemy.mesh.position.set(enemy.x, enemy.y, 0);\n\n        if (enemy.type === 'goomba') {\n          const wobble = Math.sin(globalTicks * 0.22) * 0.12;\n          enemy.mesh.userData.foot1.position.y = 0.06 + Math.max(0, wobble);\n          enemy.mesh.userData.foot2.position.y = 0.06 + Math.max(0, -wobble);\n        }\n\n        const dx = mario.x - enemy.x;\n        const dy = mario.y - enemy.y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n\n        if (dist < 1.05 && mario.isStar) {\n          enemy.alive = false;\n          scene.remove(enemy.mesh);\n          score += 200;\n          triggerCamShake(0.25);\n          playSound('stomp');\n          spawnSparkles3D(enemy.x, enemy.y + 0.4, 14);\n          spawnFloatingText3D('+200', enemy.x, enemy.y + 0.6, '#fbbf24');\n          return;\n        }\n\n        if (enemy.type === 'koopa') {\n          if (dist < 0.95) {\n            if (mario.vy < 0 && mario.y > enemy.y + 0.22) {\n              if (enemy.state === 'walking') {\n                enemy.state = 'shell';\n                enemy.vx = 0;\n                enemy.mesh.userData.belly.visible = false;\n                enemy.mesh.userData.head.visible = false;\n                enemy.mesh.userData.s1.visible = false;\n                enemy.mesh.userData.s2.visible = false;\n                enemy.mesh.userData.shell.position.y = 0.38;\n                mario.vy = 0.36;\n                score += 200;\n                triggerCamShake(0.18);\n                playSound('stomp');\n                spawnSparkles3D(enemy.x, enemy.y + 0.3, 8);\n                spawnFloatingText3D('+200', enemy.x, enemy.y + 0.5, '#4ade80');\n              } else if (enemy.state === 'sliding') {\n                enemy.state = 'shell';\n                enemy.vx = 0;\n                mario.vy = 0.36;\n                playSound('stomp');\n                triggerCamShake(0.18);\n                spawnFloatingText3D('STOP!', enemy.x, enemy.y + 0.5, '#38bdf8');\n              }\n            } else if (enemy.state === 'shell') {\n              enemy.state = 'sliding';\n              const kickDir = mario.x < enemy.x ? 1 : -1;\n              enemy.vx = kickDir * 0.34;\n              playSound('kick');\n              triggerCamShake(0.2);\n              spawnSparkles3D(enemy.x, enemy.y + 0.3, 10);\n              spawnFloatingText3D('KICK!', enemy.x, enemy.y + 0.5, '#f59e0b');\n              if (navigator.vibrate) navigator.vibrate(20);\n            } else if (enemy.state === 'sliding' && mario.invulnerableTimer === 0) {\n              if (mario.isFire || mario.isBig) {\n                mario.isFire = false;\n                mario.isBig = false;\n                mario.h = 1.6;\n                mario3D.scale.set(1, 1, 1);\n                mario.invulnerableTimer = 60;\n                mario3D.userData.redMat.color.setHex(0xdc2626);\n                mario3D.userData.blueMat.color.setHex(0x1d4ed8);\n                mario3D.userData.capDome.material = mario3D.userData.redMat;\n                mario3D.userData.visor.material = mario3D.userData.redMat;\n                playSound('powerup');\n              } else {\n                killMario();\n              }\n            } else if (enemy.state === 'walking' && mario.invulnerableTimer === 0) {\n              if (mario.isFire || mario.isBig) {\n                mario.isFire = false;\n                mario.isBig = false;\n                mario.h = 1.6;\n                mario3D.scale.set(1, 1, 1);\n                mario.invulnerableTimer = 60;\n                mario3D.userData.redMat.color.setHex(0xdc2626);\n                mario3D.userData.blueMat.color.setHex(0x1d4ed8);\n                mario3D.userData.capDome.material = mario3D.userData.redMat;\n                mario3D.userData.visor.material = mario3D.userData.redMat;\n                playSound('powerup');\n              } else {\n                killMario();\n              }\n            }\n          }\n          return;\n        }\n\n        if (dist < 0.95) {\n          if (mario.vy < 0 && mario.y > enemy.y + 0.25) {\n            enemy.alive = false;\n            enemy.flatTimer = 25;\n            mario.vy = 0.36;\n            score += 200;\n            triggerCamShake(0.22);\n            playSound('stomp');\n            spawnSparkles3D(enemy.x, enemy.y + 0.3, 8);\n            spawnFloatingText3D('+200', enemy.x, enemy.y + 0.5, '#4ade80');\n            enemy.mesh.scale.set(1.5, 0.15, 1.5);\n            enemy.mesh.position.y -= 0.3;\n          } else if (mario.invulnerableTimer === 0) {\n            if (mario.isFire || mario.isBig) {\n              mario.isFire = false;\n              mario.isBig = false;\n              mario.h = 1.6;\n              mario3D.scale.set(1, 1, 1);\n              mario.invulnerableTimer = 60;\n              mario3D.userData.redMat.color.setHex(0xdc2626);\n              mario3D.userData.blueMat.color.setHex(0x1d4ed8);\n              mario3D.userData.capDome.material = mario3D.userData.redMat;\n              mario3D.userData.visor.material = mario3D.userData.redMat;\n              playSound('powerup');\n            } else {\n              killMario();\n            }\n          }\n        }\n      });\n\n      // 7. Update 3D Items\n      items.forEach(item => {\n        item.y += item.vy || 0;\n        item.x += item.vx || 0;\n        if (item.type === 'mushroom') {\n          item.vy = (item.vy || 0) - 0.015;\n          const ty = Math.floor(item.y);\n          const tx = Math.floor(item.x);\n          if (getTile(tx, ty) > 0) {\n            item.y = ty + 1;\n            item.vy = 0;\n          }\n          item.mesh.position.set(item.x, item.y, 0);\n          item.mesh.rotation.y += 0.04;\n\n          const dx = mario.x - item.x;\n          const dy = mario.y - item.y;\n          if (Math.sqrt(dx * dx + dy * dy) < 1.0) {\n            item.collected = true;\n            scene.remove(item.mesh);\n            mario.isBig = true;\n            mario.h = 2.1;\n            mario3D.scale.set(1.35, 1.35, 1.35);\n            score += 1000;\n            triggerCamShake(0.3);\n            spawnSparkles3D(mario.x, mario.y + 1.0, 16);\n            spawnFloatingText3D('+1000', mario.x, mario.y + 1.4, '#f43f5e');\n            playSound('powerup');\n          }\n        } else if (item.type === 'flower') {\n          item.mesh.rotation.y += 0.05;\n          const dx = mario.x - item.x;\n          const dy = mario.y - item.y;\n          if (Math.sqrt(dx * dx + dy * dy) < 1.0) {\n            item.collected = true;\n            scene.remove(item.mesh);\n            mario.isFire = true;\n            mario.isBig = true;\n            mario.h = 2.1;\n            mario3D.scale.set(1.35, 1.35, 1.35);\n            score += 1000;\n            triggerCamShake(0.24);\n            playSound('powerup');\n            spawnSparkles3D(mario.x, mario.y + 1.0, 16);\n            spawnFloatingText3D('FIRE MARIO!', mario.x, mario.y + 1.4, '#f97316');\n\n            mario3D.userData.blueMat.color.setHex(0xf8fafc);\n            const whiteCapMat = new THREE.MeshStandardMaterial({ color: 0xf8fafc, roughness: 0.5 });\n            mario3D.userData.capDome.material = whiteCapMat;\n            mario3D.userData.visor.material = whiteCapMat;\n          }\n        } else if (item.type === 'star') {\n          item.x += item.vx;\n          item.y += item.vy;\n          item.vy -= 0.015;\n          item.mesh.rotation.y += 0.08;\n          item.mesh.rotation.z += 0.04;\n\n          const ty = Math.floor(item.y);\n          const tx = Math.floor(item.x);\n          if (getTile(tx, ty) > 0) {\n            item.y = ty + 1.0;\n            item.vy = 0.22;\n          }\n\n          const dx = mario.x - item.x;\n          const dy = mario.y - item.y;\n          if (Math.sqrt(dx * dx + dy * dy) < 1.1) {\n            item.collected = true;\n            scene.remove(item.mesh);\n            mario.isStar = true;\n            mario.starTimer = 750;\n            score += 1000;\n            triggerCamShake(0.3);\n            playSound('powerup');\n            startStarmanBGM();\n            spawnSparkles3D(mario.x, mario.y + 1.0, 20);\n            spawnFloatingText3D('STARMAN!', mario.x, mario.y + 1.4, '#fbbf24');\n          }\n        } else if (item.type === 'coin') {\n          // Floating spinning 3D coin\n          item.mesh.rotation.y += 0.08;\n          item.mesh.position.y = item.baseY + Math.sin(globalTicks * 0.12 + item.baseX * 2) * 0.1;\n          const dx = mario.x - item.x;\n          const dy = (mario.y + mario.h * 0.5) - item.y;\n          if (Math.abs(dx) < 0.72 && Math.abs(dy) < 0.95) {\n            item.collected = true;\n            scene.remove(item.mesh);\n            coins++;\n            score += 200;\n            playSound('coin');\n            spawnCoinPop3D(item.x, item.y + 0.2);\n            spawnSparkles3D(item.x, item.y + 0.2, 7);\n            spawnFloatingText3D('+200', item.x, item.y + 0.4);\n          }\n        }\n      });\n      items = items.filter(i => !i.collected);\n\n      // Fireball Shooting (Shift / X or mobile B)\n      if (fireballCooldown > 0) fireballCooldown--;\n      if (keys.fire && mario.isFire && fireballCooldown === 0) {\n        spawnFireball3D(mario.x + (mario.facing === 'left' ? -0.4 : 0.4), mario.y + 1.0, mario.facing === 'left' ? -1 : 1);\n        fireballCooldown = 14;\n      }\n\n      for (let i = fireballs.length - 1; i >= 0; i--) {\n        const fb = fireballs[i];\n        fb.x += fb.vx;\n        fb.y += fb.vy;\n        fb.vy -= 0.016;\n\n        const footTile = getTile(Math.floor(fb.x), Math.floor(fb.y));\n        if (footTile > 0) {\n          fb.y = Math.floor(fb.y) + 1.0;\n          fb.vy = 0.22;\n          fb.bounces++;\n          playSound('bump');\n          spawnSparkles3D(fb.x, fb.y, 3);\n        }\n\n        const wallTile = getTile(Math.floor(fb.x + (fb.vx > 0 ? 0.25 : -0.25)), Math.floor(fb.y + 0.3));\n        if (wallTile > 0 || fb.bounces >= 4) {\n          scene.remove(fb.mesh);\n          spawnSparkles3D(fb.x, fb.y, 8);\n          fireballs.splice(i, 1);\n          continue;\n        }\n\n        fb.mesh.position.set(fb.x, fb.y, 0);\n        fb.mesh.rotation.x += 0.2;\n        fb.mesh.rotation.y += 0.2;\n\n        let hitEnemy = false;\n        enemies.forEach(en => {\n          if (en.alive && !hitEnemy) {\n            const dX = fb.x - en.x;\n            const dY = fb.y - en.y;\n            if (Math.abs(dX) < 0.65 && Math.abs(dY) < 0.7) {\n              en.alive = false;\n              scene.remove(en.mesh);\n              score += 200;\n              hitEnemy = true;\n              playSound('stomp');\n              triggerCamShake(0.2);\n              spawnSparkles3D(en.x, en.y + 0.4, 12);\n              spawnFloatingText3D('+200', en.x, en.y + 0.5, '#f97316');\n            }\n          }\n        });\n\n        if (hitEnemy) {\n          scene.remove(fb.mesh);\n          spawnSparkles3D(fb.x, fb.y, 8);\n          fireballs.splice(i, 1);\n        }\n      }\n\n      // Starman Rainbow Strobe & Countdown\n      const starBadge = document.getElementById('starBadge');\n      if (mario.isStar) {\n        mario.starTimer--;\n        starBadge.style.display = 'inline-block';\n        starBadge.innerText = '\u2b50 STAR ' + Math.ceil(mario.starTimer / 50) + 's';\n\n        const hue = (globalTicks * 0.08) % 1.0;\n        mario3D.userData.redMat.color.setHSL(hue, 1, 0.55);\n        mario3D.userData.blueMat.color.setHSL((hue + 0.3) % 1.0, 1, 0.55);\n\n        if (globalTicks % 3 === 0) {\n          spawnSparkles3D(mario.x + (Math.random() - 0.5) * 0.4, mario.y + 0.8, 2);\n        }\n\n        if (mario.starTimer <= 0) {\n          mario.isStar = false;\n          starBadge.style.display = 'none';\n          stopStarmanBGM();\n          startMarioBGM();\n\n          if (mario.isFire) {\n            mario3D.userData.blueMat.color.setHex(0xf8fafc);\n          } else {\n            mario3D.userData.redMat.color.setHex(0xdc2626);\n            mario3D.userData.blueMat.color.setHex(0x1d4ed8);\n            mario3D.userData.capDome.material = mario3D.userData.redMat;\n            mario3D.userData.visor.material = mario3D.userData.redMat;\n          }\n        }\n      } else {\n        starBadge.style.display = 'none';\n      }\n\n      // Record Player Run for Ghost Mode\n      if (globalTicks % 3 === 0 && mario.x < 188) {\n        recordedRunFrames.push([Math.round(mario.x * 100) / 100, Math.round(mario.y * 100) / 100, mario.facing]);\n      }\n\n      // Animate Holographic Ghost Mario\n      const diffBadge = document.getElementById('ghostDiffBadge');\n      if (ghost3D && ghost3D.visible && ghostReplay && ghostReplay.path && ghostReplay.path.length > 0) {\n        const frameIdx = Math.floor(globalTicks / 3);\n        if (frameIdx < ghostReplay.path.length) {\n          const gFrame = ghostReplay.path[frameIdx];\n          ghost3D.position.set(gFrame[0], gFrame[1], -0.2);\n          ghost3D.rotation.y = gFrame[2] === 'left' ? -Math.PI / 2 : Math.PI / 2;\n\n          const distDiff = mario.x - gFrame[0];\n          if (distDiff >= 0) {\n            diffBadge.innerText = 'GHOST: +' + distDiff.toFixed(1) + 'm';\n            diffBadge.style.color = '#4ade80';\n          } else {\n            diffBadge.innerText = 'GHOST: ' + distDiff.toFixed(1) + 'm';\n            diffBadge.style.color = '#f87171';\n          }\n        } else {\n          diffBadge.innerText = 'GHOST CLEAR';\n        }\n      } else {\n        diffBadge.innerText = 'GHOST: READY';\n      }\n\n      // 8. Update 3D Particles & VFX\n      for (let i = particles3D.length - 1; i >= 0; i--) {\n        const p = particles3D[i];\n        p.mesh.position.add(p.velocity);\n\n        if (p.isSparkle) {\n          p.velocity.y -= 0.004;\n          p.mesh.rotation.x += 0.2;\n          p.mesh.rotation.y += 0.25;\n          const sc = (p.life / 28) * 0.15;\n          p.mesh.scale.set(sc, sc, sc);\n        } else if (p.isRing) {\n          p.mesh.scale.multiplyScalar(1.08);\n          p.mesh.material.opacity = p.life / 14;\n        } else if (p.isTextSprite) {\n          p.velocity.y *= 0.94;\n          p.mesh.material.opacity = Math.min(1, p.life / 20);\n        } else if (p.isFirework) {\n          p.velocity.y -= 0.005;\n          p.velocity.multiplyScalar(0.97);\n          const sc = Math.max(0.01, (p.life / 36) * 0.14);\n          p.mesh.scale.set(sc, sc, sc);\n        } else {\n          p.velocity.y -= 0.014;\n          p.mesh.rotation.x += 0.12;\n          p.mesh.rotation.y += 0.12;\n        }\n\n        p.life--;\n        if (p.life <= 0) {\n          scene.remove(p.mesh);\n          particles3D.splice(i, 1);\n        }\n      }\n\n      // 9. Smooth 3D Cinematic Tracking Camera\n      const targetCamX = mario.x + 3.5;\n      const targetCamY = Math.max(5.5, mario.y + 2.2);\n      camera.position.x += (targetCamX - camera.position.x) * 0.12;\n      camera.position.y += (targetCamY - camera.position.y) * 0.12;\n\n      // Apply Dynamic Camera Micro-Shake Juice\n      if (camShake > 0) {\n        camera.position.x += (Math.random() - 0.5) * camShake;\n        camera.position.y += (Math.random() - 0.5) * camShake;\n        camShake *= 0.85;\n        if (camShake < 0.005) camShake = 0;\n      }\n\n      camera.lookAt(camera.position.x, camera.position.y - 1.2, 0);\n\n      clouds3D.forEach(c => {\n        c.position.x += 0.005;\n        if (c.position.x > LEVEL_WIDTH + 15) c.position.x = -15;\n      });\n\n      if (mario.invulnerableTimer > 0) mario.invulnerableTimer--;\n\n      document.getElementById('hudScore').innerText = String(score).padStart(6, '0');\n      document.getElementById('hudCoins').innerHTML = '<span class=\"coin-icon\"></span>x' + String(coins).padStart(2, '0');\n      document.getElementById('hudLives').innerText = 'x' + lives;\n    }\n\n    // Rock-Solid Horizontal Collision (Never gets stuck on ground!)\n    function handleTileCollisionX() {\n      const minX = Math.floor(mario.x - 0.32);\n      const maxX = Math.floor(mario.x + 0.32);\n      // Key fix: ONLY check from y + 0.25 to y + h - 0.1!\n      // The ground block at y <= mario.y is never treated as a wall!\n      const minY = Math.floor(mario.y + 0.25);\n      const maxY = Math.floor(mario.y + mario.h - 0.1);\n\n      for (let ty = minY; ty <= maxY; ty++) {\n        for (let tx = minX; tx <= maxX; tx++) {\n          const t = getTile(tx, ty);\n          if (t > 0) {\n            if (mario.vx > 0) {\n              mario.x = tx - 0.33;\n              mario.vx = 0;\n            } else if (mario.vx < 0) {\n              mario.x = tx + 1 + 0.33;\n              mario.vx = 0;\n            }\n            return;\n          }\n        }\n      }\n    }\n\n    // Rock-Solid Vertical Collision (Floor landing & Ceiling bumping)\n    function handleTileCollisionY() {\n      const minX = Math.floor(mario.x - 0.28);\n      const maxX = Math.floor(mario.x + 0.28);\n\n      if (mario.vy <= 0) {\n        // Falling down - check ground beneath feet\n        const footTileY = Math.floor(mario.y);\n        for (let tx = minX; tx <= maxX; tx++) {\n          const t = getTile(tx, footTileY);\n          if (t > 0) {\n            mario.y = footTileY + 1.0;\n            mario.vy = 0;\n            mario.isGrounded = true;\n            return;\n          }\n        }\n      } else {\n        // Jumping up - check ceiling above head\n        const headTileY = Math.floor(mario.y + mario.h);\n        for (let tx = minX; tx <= maxX; tx++) {\n          const t = getTile(tx, headTileY);\n          if (t > 0) {\n            mario.y = headTileY - mario.h;\n            mario.vy = 0;\n            jumpHoldTicks = 0;\n            bumpBlock3D(tx, headTileY, t);\n            return;\n          }\n        }\n      }\n    }\n\n    function getTile(x, y) {\n      if (x < 0 || x >= LEVEL_WIDTH || y < 0 || y >= LEVEL_HEIGHT) return 0;\n      return levelGrid[y][x];\n    }\n\n    function bumpBlock3D(tx, ty, tile) {\n      const mesh = tileMeshes.get(`${tx},${ty}`);\n      if (mesh) {\n        mesh.position.y += 0.42;\n        mesh.scale.set(1.15, 0.85, 1.15);\n        setTimeout(() => {\n          if (mesh) {\n            mesh.position.y -= 0.42;\n            mesh.scale.set(1, 1, 1);\n          }\n        }, 85);\n      }\n      spawnShockwave3D(tx + 0.5, ty + 0.5);\n      triggerCamShake(0.14);\n\n      if (tile === 3) {\n        // Coin Block\n        levelGrid[ty][tx] = 11;\n        if (mesh) mesh.material = mats.questionEmpty;\n        coins++;\n        score += 200;\n        playSound('coin');\n        spawnCoinPop3D(tx + 0.5, ty + 1.2);\n        spawnSparkles3D(tx + 0.5, ty + 1.2, 8);\n        spawnFloatingText3D('+200', tx + 0.5, ty + 1.4);\n      } else if (tile === 4) {\n        // Super Mushroom / Fire Flower / Star Block\n        levelGrid[ty][tx] = 11;\n        if (mesh) mesh.material = mats.questionEmpty;\n\n        if (tx === 80 || tx === 33) {\n          spawnStar3D(tx + 0.5, ty + 1.2);\n          spawnSparkles3D(tx + 0.5, ty + 1.2, 16);\n          playSound('powerup');\n        } else if (mario.isBig || mario.isFire) {\n          spawnFireFlower3D(tx + 0.5, ty + 1.2);\n          spawnSparkles3D(tx + 0.5, ty + 1.2, 12);\n          playSound('powerup');\n        } else {\n          spawnMushroom3D(tx + 0.5, ty + 1.2);\n          spawnSparkles3D(tx + 0.5, ty + 1.2, 12);\n          playSound('powerup');\n        }\n      } else if (tile === 2) {\n        if (mario.isBig) {\n          levelGrid[ty][tx] = 0;\n          if (mesh) scene.remove(mesh);\n          tileMeshes.delete(`${tx},${ty}`);\n          score += 50;\n          triggerCamShake(0.28);\n          spawnBrickDebris3D(tx + 0.5, ty + 0.5);\n          spawnSparkles3D(tx + 0.5, ty + 0.5, 6);\n          playSound('stomp');\n        } else {\n          playSound('bump');\n        }\n      }\n    }\n\n    // ==================== JUICE & VFX ENGINE ====================\n    let camShake = 0;\n    let wasGroundedLastFrame = true;\n    let marioSquashY = 1.0;\n    let marioSquashX = 1.0;\n\n    function triggerCamShake(amount) {\n      camShake = Math.max(camShake, amount);\n    }\n\n    // Radiant Golden Diamond / Star Sparkles\n    function spawnSparkles3D(x, y, count = 8) {\n      const sparkleMat = new THREE.MeshStandardMaterial({\n        color: 0xfef08a,\n        emissive: 0xfacc15,\n        emissiveIntensity: 0.8,\n        roughness: 0.2,\n      });\n      const geo = new THREE.OctahedronGeometry(0.12, 0);\n\n      for (let i = 0; i < count; i++) {\n        const p = new THREE.Mesh(geo, sparkleMat);\n        p.position.set(x, y, (Math.random() - 0.5) * 0.4);\n        scene.add(p);\n        const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.5;\n        const speed = 0.06 + Math.random() * 0.08;\n        particles3D.push({\n          mesh: p,\n          velocity: new THREE.Vector3(Math.cos(angle) * speed, Math.sin(angle) * speed + 0.04, (Math.random() - 0.5) * 0.05),\n          life: 22 + Math.floor(Math.random() * 10),\n          isSparkle: true,\n        });\n      }\n    }\n\n    // Shockwave Ring Expanding on Block Bumps\n    function spawnShockwave3D(x, y) {\n      const ringGeo = new THREE.RingGeometry(0.2, 0.35, 24);\n      const ringMat = new THREE.MeshBasicMaterial({\n        color: 0xffffff,\n        side: THREE.DoubleSide,\n        transparent: true,\n        opacity: 0.8,\n      });\n      const ring = new THREE.Mesh(ringGeo, ringMat);\n      ring.position.set(x, y, 0.1);\n      scene.add(ring);\n      particles3D.push({\n        mesh: ring,\n        velocity: new THREE.Vector3(0, 0, 0),\n        life: 14,\n        isRing: true,\n        scaleSpeed: 0.16,\n      });\n    }\n\n    // Floating Score Canvas Sprites (+200, +1000)\n    function spawnFloatingText3D(text, x, y, color = '#facc15') {\n      const tc = document.createElement('canvas');\n      tc.width = 256;\n      tc.height = 128;\n      const tctx = tc.getContext('2d');\n      tctx.font = 'bold 52px \"Press Start 2P\", cursive';\n      tctx.textAlign = 'center';\n      tctx.textBaseline = 'middle';\n      tctx.fillStyle = '#000000';\n      tctx.fillText(text, 130, 66);\n      tctx.fillStyle = color;\n      tctx.fillText(text, 128, 64);\n\n      const texture = new THREE.CanvasTexture(tc);\n      const spriteMat = new THREE.SpriteMaterial({ map: texture, transparent: true, opacity: 1 });\n      const sprite = new THREE.Sprite(spriteMat);\n      sprite.position.set(x, y + 0.6, 0.4);\n      sprite.scale.set(1.4, 0.7, 1);\n      scene.add(sprite);\n\n      particles3D.push({\n        mesh: sprite,\n        velocity: new THREE.Vector3(0, 0.04, 0),\n        life: 38,\n        isTextSprite: true,\n      });\n    }\n\n    // Sky Fireworks on Victory\n    function spawnFirework3D(x, y) {\n      playSound('firework');\n      triggerCamShake(0.18);\n      const colors = [0xef4444, 0xf59e0b, 0x10b981, 0x38bdf8, 0xc084fc, 0xf43f5e];\n      const col = colors[Math.floor(Math.random() * colors.length)];\n      const fMat = new THREE.MeshBasicMaterial({ color: col });\n      const geo = new THREE.SphereGeometry(0.14, 6, 6);\n\n      for (let i = 0; i < 18; i++) {\n        const p = new THREE.Mesh(geo, fMat);\n        p.position.set(x, y, 0);\n        scene.add(p);\n        const theta = Math.random() * Math.PI * 2;\n        const phi = Math.random() * Math.PI;\n        const spd = 0.12 + Math.random() * 0.16;\n        particles3D.push({\n          mesh: p,\n          velocity: new THREE.Vector3(\n            Math.sin(phi) * Math.cos(theta) * spd,\n            Math.sin(phi) * Math.sin(theta) * spd + 0.03,\n            Math.cos(phi) * spd * 0.5\n          ),\n          life: 30 + Math.floor(Math.random() * 12),\n          isFirework: true,\n        });\n      }\n    }\n\n    // ==================== POWER-UPS & FIREBALLS & GHOST ====================\n    let fireballs = [];\n    let fireballCooldown = 0;\n    let recordedRunFrames = [];\n    let ghostReplay = null;\n    let ghost3D = null;\n\n    function spawnFireFlower3D(x, y) {\n      const g = new THREE.Group();\n      const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.4, 12), new THREE.MeshStandardMaterial({ color: 0x16a34a }));\n      stem.position.y = 0.2;\n      g.add(stem);\n\n      const petalColors = [0xef4444, 0xfacc15, 0xffffff, 0xef4444];\n      for (let i = 0; i < 4; i++) {\n        const petal = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 12), new THREE.MeshStandardMaterial({ color: petalColors[i], emissive: petalColors[i], emissiveIntensity: 0.3 }));\n        const a = (i * Math.PI) / 2;\n        petal.position.set(Math.cos(a) * 0.18, 0.42 + Math.sin(a) * 0.18, 0);\n        g.add(petal);\n      }\n      const center = new THREE.Mesh(new THREE.SphereGeometry(0.12, 12, 12), new THREE.MeshStandardMaterial({ color: 0xf97316 }));\n      center.position.set(0, 0.42, 0.05);\n      g.add(center);\n\n      g.position.set(x, y, 0);\n      scene.add(g);\n      items.push({ type: 'flower', x, y, vy: 0.05, mesh: g });\n    }\n\n    function spawnStar3D(x, y) {\n      const g = new THREE.Group();\n      const starGeo = new THREE.OctahedronGeometry(0.32, 0);\n      const starMat = new THREE.MeshStandardMaterial({ color: 0xfbbf24, emissive: 0xf59e0b, emissiveIntensity: 0.8, metalness: 0.8, roughness: 0.2 });\n      const starMesh = new THREE.Mesh(starGeo, starMat);\n      starMesh.scale.set(1.1, 1.3, 0.6);\n      g.add(starMesh);\n\n      g.position.set(x, y, 0);\n      scene.add(g);\n      items.push({ type: 'star', x, y, vx: 0.045, vy: 0.2, mesh: g });\n    }\n\n    function spawnFireball3D(x, y, dir) {\n      if (fireballs.length >= 2) return;\n      playSound('fireball');\n      triggerCamShake(0.08);\n      if (navigator.vibrate) navigator.vibrate(12);\n\n      const fGeo = new THREE.SphereGeometry(0.18, 12, 12);\n      const fMat = new THREE.MeshStandardMaterial({ color: 0xf97316, emissive: 0xfacc15, emissiveIntensity: 1.0 });\n      const mesh = new THREE.Mesh(fGeo, fMat);\n      mesh.position.set(x, y, 0);\n      scene.add(mesh);\n\n      fireballs.push({\n        mesh,\n        x,\n        y,\n        vx: dir * 0.28,\n        vy: -0.06,\n        bounces: 0,\n      });\n    }\n\n    function createGhostMarioMesh() {\n      const ghost = createRealMarioMesh();\n      const ghostMat = new THREE.MeshStandardMaterial({\n        color: 0x38bdf8,\n        emissive: 0x0284c7,\n        emissiveIntensity: 0.4,\n        transparent: true,\n        opacity: 0.45,\n        roughness: 0.3\n      });\n      ghost.traverse(child => {\n        if (child.isMesh) child.material = ghostMat;\n      });\n      ghost.visible = false;\n      scene.add(ghost);\n      return ghost;\n    }\n\n    function spawnCoinPop3D(x, y) {\n      const coinMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, 0.08, 16), mats.coin);\n      coinMesh.rotation.x = Math.PI / 2;\n      coinMesh.position.set(x, y, 0);\n      scene.add(coinMesh);\n\n      let dy = 0.24;\n      const coinInterval = setInterval(() => {\n        coinMesh.position.y += dy;\n        coinMesh.rotation.y += 0.35;\n        dy -= 0.022;\n        if (dy < -0.16) {\n          clearInterval(coinInterval);\n          scene.remove(coinMesh);\n        }\n      }, 20);\n    }\n\n    function spawnFloatingCoin3D(x, y) {\n      const coinMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.07, 16), mats.coin);\n      coinMesh.rotation.x = Math.PI / 2;\n      coinMesh.position.set(x, y, 0);\n      coinMesh.castShadow = true;\n      scene.add(coinMesh);\n      items.push({ type: 'coin', baseX: x, baseY: y, x: x, y: y, mesh: coinMesh });\n    }\n\n    function spawnMushroom3D(x, y) {\n      const g = new THREE.Group();\n      const cap = new THREE.Mesh(new THREE.SphereGeometry(0.42, 16, 16, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: 0xef4444 }));\n      cap.position.y = 0.3;\n      const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.32, 16), new THREE.MeshStandardMaterial({ color: 0xfef08a }));\n      g.add(cap, stem);\n      g.position.set(x, y, 0);\n      scene.add(g);\n      items.push({ type: 'mushroom', x, y, vx: 0.04, vy: 0.12, mesh: g });\n    }\n\n    function spawnBrickDebris3D(x, y) {\n      const vels = [\n        new THREE.Vector3(-0.09, 0.18, 0.05),\n        new THREE.Vector3(0.09, 0.18, -0.05),\n        new THREE.Vector3(-0.13, 0.09, -0.05),\n        new THREE.Vector3(0.13, 0.09, 0.05),\n      ];\n      vels.forEach(v => {\n        const piece = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.38, 0.38), mats.brick);\n        piece.position.set(x, y, 0);\n        scene.add(piece);\n        particles3D.push({ mesh: piece, velocity: v, life: 36 });\n      });\n    }\n\n    function spawnDust3D(x, y) {\n      for (let i = 0; i < 4; i++) {\n        const p = new THREE.Mesh(new THREE.SphereGeometry(0.12, 6, 6), mats.cloud);\n        p.position.set(x + (Math.random() * 0.4 - 0.2), y + 0.1, 0);\n        scene.add(p);\n        particles3D.push({\n          mesh: p,\n          velocity: new THREE.Vector3((Math.random() - 0.5) * 0.05, Math.random() * 0.05, 0),\n          life: 15,\n        });\n      }\n    }\n\n    function killMario() {\n      lives--;\n      stopMarioBGM();\n      playSound('gameover');\n      if (lives <= 0) {\n        gameState = 'GAMEOVER';\n        document.getElementById('finalScoreMsg').innerText = 'FINAL SCORE: ' + score;\n        document.getElementById('gameOverOverlay').classList.remove('hidden');\n      } else {\n        mario.x = 3.5;\n        mario.y = 2.0;\n        mario.vx = 0;\n        mario.vy = 0;\n      }\n    }\n\n    function victory() {\n      gameState = 'VICTORY';\n      stopMarioBGM();\n      stopStarmanBGM();\n      const elapsedSeconds = 400 - timeLeft;\n      score += timeLeft * 50;\n      playSound('powerup');\n\n      let recordMsg = 'STAGE CLEAR! TIME: ' + elapsedSeconds + 's (SCORE: ' + score + ')';\n      document.getElementById('victoryScoreMsg').innerText = recordMsg;\n      document.getElementById('victoryOverlay').classList.remove('hidden');\n\n      if (!ghostReplay || elapsedSeconds < ghostReplay.time) {\n        fetch('/api/ghost', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ name: 'SpeedHero', time: elapsedSeconds, path: recordedRunFrames }),\n        }).then(r => r.json()).then(d => {\n          if (d.newRecord) {\n            document.getElementById('victoryScoreMsg').innerText = '\ud83c\udfc6 NEW SPEEDRUN RECORD! ' + elapsedSeconds + 's! SCORE: ' + score;\n            ghostReplay = d.record;\n          }\n        }).catch(e => {});\n      }\n\n      for (let i = 0; i < 8; i++) {\n        setTimeout(() => {\n          spawnFirework3D(196 + (Math.random() - 0.5) * 12, 9 + Math.random() * 6);\n        }, i * 350);\n      }\n    }\n\n    function gameLoop() {\n      update();\n      renderer.render(scene, camera);\n      if (gameState === 'PLAYING') {\n        requestAnimationFrame(gameLoop);\n      }\n    }\n\n    // Keyboard Controls\n    window.addEventListener('keydown', (e) => {\n      if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = true;\n      if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = true;\n      if (e.code === 'ArrowUp' || e.code === 'Space' || e.code === 'KeyW' || e.code === 'KeyZ') keys.jump = true;\n      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight' || e.code === 'KeyX') keys.fire = true;\n    });\n\n    window.addEventListener('keyup', (e) => {\n      if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;\n      if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;\n      if (e.code === 'ArrowUp' || e.code === 'Space' || e.code === 'KeyW' || e.code === 'KeyZ') keys.jump = false;\n      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight' || e.code === 'KeyX') keys.fire = false;\n    });\n\n    // Mobile Virtual Touch Controls\n    const mLeft = document.getElementById('mLeft');\n    const mRight = document.getElementById('mRight');\n    const mJump = document.getElementById('mJump');\n    const mFire = document.getElementById('mFire');\n\n    mLeft.addEventListener('touchstart', (e) => { e.preventDefault(); keys.left = true; });\n    mLeft.addEventListener('touchend', (e) => { e.preventDefault(); keys.left = false; });\n    mRight.addEventListener('touchstart', (e) => { e.preventDefault(); keys.right = true; });\n    mRight.addEventListener('touchend', (e) => { e.preventDefault(); keys.right = false; });\n    mJump.addEventListener('touchstart', (e) => { e.preventDefault(); keys.jump = true; getAudio(); });\n    mJump.addEventListener('touchend', (e) => { e.preventDefault(); keys.jump = false; });\n    mFire.addEventListener('touchstart', (e) => { e.preventDefault(); keys.fire = true; });\n    mFire.addEventListener('touchend', (e) => { e.preventDefault(); keys.fire = false; });\n\n    // UI Buttons & Leaderboard Integration\n    function hideAllOverlays() {\n      document.querySelectorAll('.overlay').forEach(el => el.classList.add('hidden'));\n    }\n\n    document.getElementById('hudAudioToggle').addEventListener('click', () => {\n      isBgmMuted = !isBgmMuted;\n      document.getElementById('audioToggleLabel').innerText = isBgmMuted ? '\ud83d\udd07 OFF' : '\ud83d\udd0a BGM';\n      if (!isBgmMuted && gameState === 'PLAYING' && !isBgmPlaying) {\n        startMarioBGM();\n      }\n    });\n\n    const mDown = document.getElementById('mDown');\n    if (mDown) {\n      mDown.addEventListener('touchstart', (e) => { e.preventDefault(); if (navigator.vibrate) navigator.vibrate(10); });\n      mDown.addEventListener('touchend', (e) => { e.preventDefault(); });\n    }\n\n    const btnFs = document.getElementById('btnFullscreen');\n    if (btnFs) {\n      btnFs.addEventListener('click', () => {\n        if (!document.fullscreenElement) {\n          document.documentElement.requestFullscreen().catch(err => {});\n          btnFs.innerText = '\u2715';\n        } else {\n          document.exitFullscreen().catch(err => {});\n          btnFs.innerText = '\u26f6';\n        }\n      });\n    }\n\n    async function loadSpeedrunGhost() {\n      try {\n        const res = await fetch('/api/ghost');\n        const data = await res.json();\n        if (data && data.time) {\n          ghostReplay = data;\n          document.getElementById('ghostDiffBadge').innerText = 'RECORD: ' + data.time + 's (' + (data.country || 'GE') + ')';\n        }\n      } catch (e) {}\n    }\n    loadSpeedrunGhost();\n\n    document.getElementById('btnStartGame').addEventListener('click', startGame);\n    document.getElementById('btnRetryGame').addEventListener('click', startGame);\n    document.getElementById('btnPlayAgain').addEventListener('click', startGame);\n\n    document.getElementById('btnShowLeaderboard').addEventListener('click', async () => {\n      hideAllOverlays();\n      document.getElementById('leaderboardOverlay').classList.remove('hidden');\n      const tbody = document.getElementById('leaderboardBody');\n      tbody.innerHTML = '<tr><td colspan=\"5\">Loading scores...</td></tr>';\n      try {\n        const res = await fetch('/api/scores');\n        const scores = await res.json();\n        tbody.innerHTML = scores.map((s, idx) => `\n          <tr>\n            <td>${idx + 1}</td>\n            <td style=\"color:#38bdf8;\">${escapeHtml(s.name)}</td>\n            <td style=\"color:#f59e0b;\">${s.score}</td>\n            <td>${s.coins || 0}</td>\n            <td>${s.country || 'GE'}</td>\n          </tr>\n        `).join('');\n      } catch (e) {\n        tbody.innerHTML = '<tr><td colspan=\"5\">Failed to load</td></tr>';\n      }\n    });\n\n    document.getElementById('btnHideLeaderboard').addEventListener('click', () => {\n      hideAllOverlays();\n      document.getElementById('startOverlay').classList.remove('hidden');\n    });\n\n    document.getElementById('btnSubmitScore').addEventListener('click', async () => {\n      const name = document.getElementById('playerNameInput').value.trim() || 'Mario3D';\n      await fetch('/api/score', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ name, score, coins, time: 400 - timeLeft }),\n      });\n      document.getElementById('btnShowLeaderboard').click();\n    });\n\n    document.getElementById('btnSubmitVictory').addEventListener('click', async () => {\n      const name = document.getElementById('victoryNameInput').value.trim() || 'Hero3D';\n      await fetch('/api/score', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ name, score, coins, time: 400 - timeLeft }),\n      });\n      document.getElementById('btnShowLeaderboard').click();\n    });\n\n    function escapeHtml(str) {\n      return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n    }\n  </script>\n</body>\n</html>\n";
